export const BUNDLED_SCRIPT_PACKS: Record<string, BundledScriptPack> = {
  "sdlc": {"files":{".shared/checks.ts":"/**\n * The deliver pack's one pull-request check reader and its gate policy.\n *\n * Both sources return the same units, so `check-ci`, `ci-note` and `flip-ready`\n * classify one shape whichever source read it. ./forge.ts owns which source a\n * run selected; this file owns how a read is performed and how it gates.\n */\n\nimport {\n  CONCLUDED_CHECK_STATES,\n  forgeSource,\n  preferredChecks,\n  readChecks,\n  type CheckUnit,\n  type ForgeSource,\n  type QualifiedPr,\n} from './forge.ts';\n\n/** Checks for one read. `revision` is null when the source does not report the evaluated head. */\nexport interface CheckRead {\n  readonly source: ForgeSource;\n  readonly revision: string | null;\n  readonly units: readonly CheckUnit[];\n}\n\n/**\n * The pack's gate policy over one read. A running check wins, so a gate never\n * concludes while anything is still running; red and unknown both block; gated\n * is reported as a maintainer's gate, never as green.\n */\nexport type GateState = 'none' | 'pending' | 'red' | 'gated' | 'green';\n\nexport function gateState(units: readonly CheckUnit[]): GateState {\n  if (units.length === 0) return 'none';\n  if (units.some(unit => unit.state === 'pending')) return 'pending';\n  if (units.some(unit => unit.state === 'red' || unit.state === 'unknown')) return 'red';\n  if (units.some(unit => unit.state === 'gated')) return 'gated';\n  return 'green';\n}\n\ninterface Ran {\n  readonly ok: boolean;\n  readonly stdout: string;\n  readonly stderr: string;\n}\n\n// Every gh call is captured: a node's stderr reaches the operator, and gh is\n// chatty there (update notices), so only this pack's own messages may.\nfunction gh(...args: string[]): Ran {\n  const result = Bun.spawnSync(['gh', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  return {\n    ok: result.exitCode === 0,\n    stdout: result.stdout.toString(),\n    stderr: result.stderr.toString(),\n  };\n}\n\n/** gh's `[HOST/]OWNER/REPO` selector for the recorded pull request. */\nfunction ghRepo(pr: QualifiedPr): string {\n  return `${pr.repo.host}/${pr.repo.path}`;\n}\n\n/** One row of `gh pr checks --json name,state`. */\nexport interface GhCheck {\n  readonly name: string;\n  readonly state: string;\n}\n\nfunction isGhCheck(value: unknown): value is GhCheck {\n  if (typeof value !== 'object' || value === null) return false;\n  const record = value as Record<string, unknown>;\n  return typeof record.name === 'string' && typeof record.state === 'string';\n}\n\n// gh's `state` before a check concludes: a check run's status, or a commit\n// status's PENDING or EXPECTED.\nconst GH_RUNNING: readonly string[] = [\n  'EXPECTED',\n  'IN_PROGRESS',\n  'PENDING',\n  'QUEUED',\n  'REQUESTED',\n  'WAITING',\n];\n\n/**\n * Classify one gh row. Once a check concludes, gh's `state` is the check run's\n * conclusion or the commit status's state, classified through the forge table\n * so gh and forge agree. gh's `bucket` is not used: it calls ACTION_REQUIRED a\n * failure, and STALE, STARTUP_FAILURE and any state it does not know pending.\n * A state this reader does not know is unknown, which the gate treats as red.\n */\nexport function ghCheckUnit(check: GhCheck): CheckUnit {\n  const unit = { name: check.name };\n  if (GH_RUNNING.includes(check.state)) {\n    return { unit, phase: 'pending', result: null, state: 'pending' };\n  }\n  const result = check.state.toLowerCase();\n  // A commit status's ERROR is its failure, as the forge plugin reads it.\n  const key = result === 'error' ? 'failure' : result;\n  const state = Object.hasOwn(CONCLUDED_CHECK_STATES, key)\n    ? CONCLUDED_CHECK_STATES[key as keyof typeof CONCLUDED_CHECK_STATES]\n    : 'unknown';\n  return { unit, phase: state === 'unknown' ? 'unknown' : 'completed', result, state };\n}\n\nfunction readGhChecks(pr: QualifiedPr): readonly CheckUnit[] {\n  const number = String(pr.number);\n  const result = gh('pr', 'checks', number, '--repo', ghRepo(pr), '--json', 'name,state');\n  let parsed: unknown;\n  try {\n    // The document decides, not the exit status: gh prints it and exits non-zero\n    // when any check is failing or pending.\n    parsed = JSON.parse(result.stdout) as unknown;\n  } catch {\n    // No document at all: either the pull request has no checks or the read\n    // failed, and gh says which only in prose. The rollup count answers that as\n    // a number. A failed observation is never evidence that no CI exists.\n    const counted = gh(\n      'pr',\n      'view',\n      number,\n      '--repo',\n      ghRepo(pr),\n      '--json',\n      'statusCheckRollup',\n      '--jq',\n      '.statusCheckRollup | length'\n    );\n    if (counted.ok && counted.stdout.trim() === '0') return [];\n    throw new Error(`could not read check state: ${result.stderr.trim()}`);\n  }\n  if (!Array.isArray(parsed) || !parsed.every(isGhCheck)) {\n    throw new Error(`unexpected check payload shape: ${result.stdout.slice(0, 200)}`);\n  }\n  return parsed.map(ghCheckUnit);\n}\n\n/** Read the recorded pull request's checks from the selected source. */\nexport function readPrChecks(pr: QualifiedPr, selected: string | undefined): CheckRead {\n  const source = forgeSource(selected);\n  if (source === 'gh') return { source, revision: null, units: readGhChecks(pr) };\n  try {\n    const observation = readChecks(pr);\n    return {\n      source,\n      revision: observation.revision,\n      units: preferredChecks(observation).units,\n    };\n  } catch (error) {\n    throw new Error(\n      `ARCHON_SDLC_FORGE=forge: ${error instanceof Error ? error.message : String(error)}`\n    );\n  }\n}\n\n/**\n * Whether the repository has any active GitHub Actions workflow; undefined when\n * that could not be read, which counts as configured. Only the gh source asks\n * this: it lets a repository without CI skip the registration grace.\n */\nexport function hasActiveWorkflows(pr: QualifiedPr): boolean | undefined {\n  // Every page: the default read stops at thirty workflows, and an active one on a\n  // later page would otherwise read as \"no CI configured\". gh applies --jq to each\n  // page and refuses --slurp with --jq, so the filter prints one id per active\n  // workflow and the lines are counted here.\n  const result = gh(\n    'api',\n    '--hostname',\n    pr.repo.host,\n    `repos/${pr.repo.path}/actions/workflows`,\n    '--paginate',\n    '--jq',\n    '.workflows[] | select(.state == \"active\") | .id'\n  );\n  if (!result.ok) return undefined;\n  return result.stdout.split('\\n').some(line => line.trim() !== '');\n}\n\n/** `name (result)` for each unit, as the operator reads it. */\nexport function describeUnits(units: readonly CheckUnit[]): string {\n  return units\n    .map(unit => (unit.result === null ? unit.unit.name : `${unit.unit.name} (${unit.result})`))\n    .join(', ');\n}\n\n/** ` at <revision>` when the source reported one. */\nexport function atRevision(read: CheckRead): string {\n  return read.revision === null ? '' : ` at ${read.revision}`;\n}\n",".shared/composition.ts":"import { createHash } from 'node:crypto';\nimport { closeSync, mkdirSync, mkdtempSync, openSync, readFileSync, writeFileSync } from 'node:fs';\nimport { arch, platform } from 'node:os';\nimport { join, resolve } from 'node:path';\nimport { projectEnvironment } from './node-env.ts';\n\nexport interface CompositionRequest {\n  /** Full commit IDs, never branch names. */\n  original_base: string;\n  base: string;\n  head: string;\n  change: string;\n  /** This identifies the entire incoming prefix, not an inferred conflicting PR. */\n  base_changes: string[];\n  method: 'merge' | 'squash';\n  check: { name: string; argv: string[]; environment: string };\n}\n\ninterface Revision {\n  commit: string;\n  tree: string;\n}\n\ninterface Subject extends Revision {\n  role: 'change-alone' | 'base-alone' | 'composition';\n}\n\ninterface Observation {\n  subject: Subject;\n  command: CompositionRequest['check'];\n  check_digest: string;\n  exit_code: number;\n  git_clean_after: boolean;\n  head_after: string;\n  log: string;\n  started_at: string;\n  finished_at: string;\n}\n\nexport interface CompositionEvidence {\n  version: 1;\n  repository: string;\n  request: CompositionRequest;\n  original_base: Revision;\n  base: Revision;\n  head: Revision;\n  merge_bases: string[] | null;\n  candidate: Revision | null;\n  runtime: { platform: string; arch: string; bun: string; git: string };\n  observations: Observation[];\n  composition: { exit_code: number; stdout: string; stderr: string } | null;\n}\n\n/**\n * Every cause archon-validate's result can carry. Only the comparison script declares\n * `interaction`: the ordinary path's classify schema and implement's omit it. Only\n * ordinary validation and implement declare `incomplete`: the comparison script\n * records an unfinished or unusable comparison as red with an empty cause.\n */\nexport const VALIDATION_RED_CAUSES = [\n  'introduced',\n  'inherited',\n  'environment',\n  'interaction',\n  'incomplete',\n  '',\n] as const;\n\nexport interface ValidationVerdict {\n  green: boolean;\n  red_cause: (typeof VALIDATION_RED_CAUSES)[number];\n  summary: string;\n}\n\nfunction object(value: unknown): Record<string, unknown> {\n  if (value === null || typeof value !== 'object' || Array.isArray(value)) {\n    throw new Error('Comparison input must be an object.');\n  }\n  return value as Record<string, unknown>;\n}\n\nfunction string(value: unknown, field: string): string {\n  if (typeof value !== 'string' || value.trim() === '' || value.includes('\\0')) {\n    throw new Error(`Comparison ${field} must be a nonempty string without NUL bytes.`);\n  }\n  return value;\n}\n\nfunction strings(value: unknown, field: string): string[] {\n  if (!Array.isArray(value)) throw new Error(`Comparison ${field} must be an array.`);\n  return value.map((item: unknown) => string(item, field));\n}\n\nexport function parseCompositionRequest(value: unknown): CompositionRequest {\n  const input = object(value);\n  const check = object(input.check);\n  if (input.method !== 'merge' && input.method !== 'squash') {\n    throw new Error(\n      'Comparison method must be merge or squash; rebase requires different evidence.'\n    );\n  }\n  const argv = strings(check.argv, 'check.argv');\n  if (argv.length === 0) throw new Error('Comparison check.argv must name the project gate.');\n  return {\n    original_base: string(input.original_base, 'original_base'),\n    base: string(input.base, 'base'),\n    head: string(input.head, 'head'),\n    change: string(input.change, 'change'),\n    base_changes: strings(input.base_changes, 'base_changes'),\n    method: input.method,\n    check: {\n      name: string(check.name, 'check.name'),\n      argv,\n      environment: string(check.environment, 'check.environment'),\n    },\n  };\n}\n\nfunction git(cwd: string, args: string[], env?: Record<string, string | undefined>): string {\n  const result = Bun.spawnSync(['git', ...args], { cwd, env, stdout: 'pipe', stderr: 'pipe' });\n  if (result.exitCode !== 0) {\n    // Only local object/worktree commands reach this helper; no credential-bearing remote is used.\n    throw new Error(\n      `Local git ${args[0]} failed (exit ${result.exitCode}): ${result.stderr.toString().trim()}`\n    );\n  }\n  return result.stdout.toString().trim();\n}\n\nfunction revision(cwd: string, id: string): Revision {\n  if (!/^[a-f0-9]+$/.test(id)) throw new Error('Comparison revisions must be full Git object IDs.');\n  const commit = git(cwd, ['rev-parse', '--verify', `${id}^{commit}`]);\n  if (commit !== id)\n    throw new Error('Comparison revisions must be full commit IDs, not abbreviations.');\n  return { commit, tree: git(cwd, ['rev-parse', `${commit}^{tree}`]) };\n}\n\nfunction digest(value: unknown): string {\n  return createHash('sha256').update(JSON.stringify(value)).digest('hex');\n}\n\n/** A caller supplies current authoritative facts; this never resolves a moving branch for it. */\nexport function evidenceMatches(\n  evidence: CompositionEvidence,\n  current: { repository: string; request: CompositionRequest; candidate: Revision }\n): boolean {\n  return (\n    evidence.repository === current.repository &&\n    digest(evidence.request) === digest(current.request) &&\n    evidence.candidate?.commit === current.candidate.commit &&\n    evidence.candidate.tree === current.candidate.tree\n  );\n}\n\nfunction passed(observation: Observation): boolean {\n  return (\n    observation.exit_code === 0 &&\n    observation.git_clean_after &&\n    observation.head_after === observation.subject.commit\n  );\n}\n\nexport function comparisonVerdict(\n  evidence: CompositionEvidence,\n  evidencePath: string\n): ValidationVerdict {\n  const composed = evidence.observations.find(item => item.subject.role === 'composition');\n  const change = evidence.observations.find(item => item.subject.role === 'change-alone');\n  const base = evidence.observations.find(item => item.subject.role === 'base-alone');\n  const identity = `${evidence.request.change} (${evidence.head.commit}) onto ${evidence.request.base_changes.join(', ') || 'the incoming base'} (${evidence.base.commit})`;\n  if (!composed) {\n    return {\n      green: false,\n      red_cause: '',\n      summary: `No composed gate ran for ${identity}: ${evidence.composition?.exit_code === 1 ? 'local composition conflicted' : 'composition evidence is incomplete'}. Evidence: ${evidencePath}.`,\n    };\n  }\n  const valid =\n    evidence.observations.length === 3 &&\n    change &&\n    base &&\n    change.subject.commit === evidence.head.commit &&\n    change.subject.tree === evidence.head.tree &&\n    base.subject.commit === evidence.base.commit &&\n    base.subject.tree === evidence.base.tree &&\n    composed.subject.commit === evidence.candidate?.commit &&\n    composed.subject.tree === evidence.candidate.tree &&\n    evidence.observations.every(\n      item =>\n        item.git_clean_after &&\n        item.head_after === item.subject.commit &&\n        item.check_digest === digest(evidence.request.check) &&\n        digest(item.command) === item.check_digest\n    );\n  if (!valid) {\n    return {\n      green: false,\n      red_cause: '',\n      summary: `Comparison evidence is incomplete, mismatched, or the gate changed a checkout. No clean-tree verdict for ${identity}. Evidence: ${evidencePath}.`,\n    };\n  }\n  if (passed(composed)) {\n    return {\n      green: true,\n      red_cause: '',\n      summary: `${evidence.request.check.name} passed on composed tree ${composed.subject.tree} for ${identity}. Evidence: ${evidencePath}.`,\n    };\n  }\n  const interaction = passed(change) && passed(base);\n  const diagnostic = readFileSync(composed.log, 'utf8').trim().slice(-2000);\n  return {\n    green: false,\n    red_cause: interaction ? 'interaction' : 'introduced',\n    summary: `${evidence.request.check.name} failed on composed tree ${composed.subject.tree} for ${identity}. ${interaction ? 'Both separate trees passed the same gate; this proves an interaction with the recorded incoming base/prefix, not a pair inferred from file overlap.' : 'Separate green evidence is absent; the cause remains introduced.'} Failing output: ${composed.log}. Evidence: ${evidencePath}.${diagnostic ? `\\nGate diagnostic (tail):\\n${diagnostic}` : ''}`,\n  };\n}\n\n/** Execute one authored project command in three clean, pinned worktrees. No remote writes. */\nexport async function compareComposition(\n  cwd: string,\n  artifacts: string,\n  request: CompositionRequest\n): Promise<{ verdict: ValidationVerdict; evidence: CompositionEvidence; path: string }> {\n  const original = revision(cwd, request.original_base);\n  const base = revision(cwd, request.base);\n  const head = revision(cwd, request.head);\n  const ancestor = Bun.spawnSync(\n    ['git', 'merge-base', '--is-ancestor', original.commit, head.commit],\n    { cwd }\n  );\n  if (ancestor.exitCode !== 0)\n    throw new Error('Original comparison base must be an ancestor of the pinned head.');\n  mkdirSync(artifacts, { recursive: true });\n  const directory = mkdtempSync(join(artifacts, 'comparison-'));\n  const path = join(directory, 'evidence.json');\n  const evidence: CompositionEvidence = {\n    version: 1,\n    repository: resolve(cwd, git(cwd, ['rev-parse', '--git-common-dir'])),\n    request,\n    original_base: original,\n    base,\n    head,\n    merge_bases: null,\n    candidate: null,\n    runtime: { platform: platform(), arch: arch(), bun: Bun.version, git: git(cwd, ['--version']) },\n    observations: [],\n    composition: null,\n  };\n  const composed = Bun.spawnSync(['git', 'merge-tree', '--write-tree', base.commit, head.commit], {\n    cwd,\n    stdout: 'pipe',\n    stderr: 'pipe',\n  });\n  evidence.composition = {\n    exit_code: composed.exitCode,\n    stdout: join(directory, 'composition.stdout.log'),\n    stderr: join(directory, 'composition.stderr.log'),\n  };\n  writeFileSync(evidence.composition.stdout, composed.stdout);\n  writeFileSync(evidence.composition.stderr, composed.stderr);\n  writeFileSync(path, JSON.stringify(evidence, null, 2));\n  if (composed.exitCode !== 0 && composed.exitCode !== 1) {\n    throw new Error(\n      `Local composition failed (exit ${composed.exitCode}). Evidence: ${path}.\\n${composed.stdout.toString()}${composed.stderr.toString()}`\n    );\n  }\n  evidence.merge_bases = git(cwd, ['merge-base', '--all', base.commit, head.commit]).split('\\n');\n  if (composed.exitCode === 0) {\n    const tree = composed.stdout.toString().trim().split('\\n')[0];\n    if (!tree || !/^[a-f0-9]+$/.test(tree))\n      throw new Error('Local composition did not return a tree ID.');\n    const parents =\n      request.method === 'merge' ? ['-p', base.commit, '-p', head.commit] : ['-p', base.commit];\n    const candidate = git(\n      cwd,\n      [\n        '-c',\n        'commit.gpgSign=false',\n        'commit-tree',\n        tree,\n        ...parents,\n        '-m',\n        'Archon composition validation',\n      ],\n      {\n        ...process.env,\n        GIT_AUTHOR_NAME: 'Archon validation',\n        GIT_AUTHOR_EMAIL: 'validation@localhost',\n        GIT_COMMITTER_NAME: 'Archon validation',\n        GIT_COMMITTER_EMAIL: 'validation@localhost',\n        GIT_AUTHOR_DATE: '2000-01-01T00:00:00Z',\n        GIT_COMMITTER_DATE: '2000-01-01T00:00:00Z',\n      }\n    );\n    evidence.candidate = { commit: candidate, tree };\n    const subjects: Subject[] = [\n      { role: 'change-alone', ...head },\n      { role: 'base-alone', ...base },\n      { role: 'composition', ...evidence.candidate },\n    ];\n    // One frozen process environment for this comparison. The caller's environment label\n    // identifies external dependencies; it is not a claim that databases/network are immutable.\n    // The gate is the project's, not part of this run, so it never sees the node's contract.\n    const env = projectEnvironment(process.env);\n    for (const subject of subjects) {\n      const worktree = join(directory, subject.role);\n      git(cwd, ['worktree', 'add', '--detach', worktree, subject.commit]);\n      try {\n        if (git(worktree, ['status', '--porcelain', '--untracked-files=all']) !== '') {\n          throw new Error('Comparison worktree is not clean before the gate.');\n        }\n        const log = join(directory, `${subject.role}.log`);\n        const fd = openSync(log, 'wx');\n        const started = new Date().toISOString();\n        let exitCode: number;\n        try {\n          const child = Bun.spawn(request.check.argv, {\n            cwd: worktree,\n            env,\n            stdout: fd,\n            stderr: fd,\n            stdin: 'ignore',\n          });\n          exitCode = await child.exited;\n        } finally {\n          closeSync(fd);\n        }\n        evidence.observations.push({\n          subject,\n          command: request.check,\n          check_digest: digest(request.check),\n          exit_code: exitCode,\n          git_clean_after: git(worktree, ['status', '--porcelain', '--untracked-files=all']) === '',\n          head_after: git(worktree, ['rev-parse', 'HEAD']),\n          log,\n          started_at: started,\n          finished_at: new Date().toISOString(),\n        });\n        writeFileSync(path, JSON.stringify(evidence, null, 2));\n      } finally {\n        git(cwd, ['worktree', 'remove', '--force', worktree]);\n      }\n    }\n  }\n  writeFileSync(path, JSON.stringify(evidence, null, 2));\n  const verdict = comparisonVerdict(evidence, path);\n  writeFileSync(join(directory, 'validation.md'), `${verdict.summary}\\n`);\n  return { verdict, evidence, path };\n}\n\nexport function readComparisonRequest(path: string): CompositionRequest {\n  return parseCompositionRequest(JSON.parse(readFileSync(path, 'utf8')) as unknown);\n}\n",".shared/forge.ts":"/**\n * Standalone client for `archon forge`, the pack's opt-in forge source.\n *\n * One switch selects the source for every forge read and write this pack makes:\n *\n *   gh     the default. The GitHub CLI, as the pack has always used it.\n *   forge  opt-in with `ARCHON_SDLC_FORGE=forge`. An installed forge plugin,\n *          reached through the host command (`ARCHON_CLI_COMMAND`) the CLI and\n *          server publish.\n *\n * The source is never inferred from what happens to be installed, and a selected\n * source that cannot answer fails the operation rather than falling back to the\n * other. A container execution receives neither variable, so it uses `gh`.\n */\n\nimport { mkdtempSync, rmSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport { note } from './io.ts';\n\nexport type ForgeSource = 'gh' | 'forge';\n\nexport function forgeSource(value: string | undefined): ForgeSource {\n  const selected = (value ?? '').trim();\n  if (selected === '' || selected === 'gh') return 'gh';\n  if (selected === 'forge') return 'forge';\n  throw new Error(`ARCHON_SDLC_FORGE must be \"gh\" (the default) or \"forge\", not \"${selected}\"`);\n}\n\nexport interface QualifiedPr {\n  readonly repo: { readonly host: string; readonly path: string };\n  readonly number: number;\n}\n\n/** The pull-request facts every later public action in a run depends on. */\nexport interface PrRecord extends QualifiedPr {\n  readonly schemaVersion: 1;\n  readonly url: string;\n  readonly head: string;\n  readonly base: string;\n  readonly is_draft: boolean;\n  readonly state: 'open' | 'closed' | 'merged';\n  readonly head_repo: { readonly host: string; readonly path: string } | null;\n  readonly head_revision: string | null;\n  readonly base_revision: string | null;\n  readonly maintainer_can_modify: boolean | null;\n}\n\n// This standalone boundary is checked against @archon/forge by forge-contract.test.ts.\nexport const CHECK_STATES = ['none', 'pending', 'green', 'red', 'gated', 'unknown'] as const;\nexport type CheckState = (typeof CHECK_STATES)[number];\n\n/**\n * How a concluded check's result gates: @archon/forge's `concludedCheckStates`,\n * which the forge plugins classify through. The gh reader in ./checks.ts uses\n * this copy so both sources classify a GitHub conclusion the same way.\n */\nexport const CONCLUDED_CHECK_STATES = {\n  success: 'green',\n  neutral: 'green',\n  skipped: 'green',\n  action_required: 'gated',\n  failure: 'red',\n  cancelled: 'red',\n  timed_out: 'red',\n  stale: 'red',\n  startup_failure: 'red',\n  unknown: 'unknown',\n} as const satisfies Record<string, Exclude<CheckState, 'none' | 'pending'>>;\n\nexport interface CheckUnit {\n  readonly unit: { readonly name: string };\n  readonly phase: 'pending' | 'running' | 'completed' | 'unknown';\n  readonly result: string | null;\n  readonly state: Exclude<CheckState, 'none'>;\n}\n\nexport interface CheckSet {\n  readonly units: readonly CheckUnit[];\n  readonly summary: { readonly state: CheckState };\n}\n\nexport interface ChecksObservation extends CheckSet {\n  readonly ref: QualifiedPr;\n  readonly revision: string;\n  readonly required: CheckSet | null;\n}\n\n/**\n * Repository identity, compared the way a forge registers it.\n *\n * Host and owner/name are case-insensitive but case-preserving: a forge answers\n * with the case it has registered, whatever case this pack asked with. Comparing\n * exactly would read a pull request that is the requested one as a different one.\n */\nexport function sameRepo(left: QualifiedPr['repo'], right: QualifiedPr['repo']): boolean {\n  return (\n    left.host.toLowerCase() === right.host.toLowerCase() &&\n    left.path.toLowerCase() === right.path.toLowerCase()\n  );\n}\n\nexport function record(value: unknown): Record<string, unknown> | undefined {\n  return typeof value === 'object' && value !== null\n    ? (value as Record<string, unknown>)\n    : undefined;\n}\n\n/**\n * A forge operation that did not produce a verified result.\n *\n * `mutation` carries the evidence a write owes its caller: which of `refused`,\n * `verification_failed` or `outcome_unknown` happened, and what may remain on the\n * forge. A caller may report it; it may never retry past an unknown outcome.\n */\nexport class ForgeOperationError extends Error {\n  constructor(\n    message: string,\n    readonly mutation: Record<string, unknown> | undefined\n  ) {\n    super(message);\n    this.name = 'ForgeOperationError';\n  }\n}\n\n/**\n * Run one typed forge operation.\n *\n * The request travels as a file so authored content — a pull-request body, a\n * review report — never appears in any process's argv.\n */\nexport function invokeForge(\n  op: string,\n  request: Record<string, unknown>\n): Record<string, unknown> | null {\n  const command = parseCommand(process.env.ARCHON_CLI_COMMAND);\n  const directory = mkdtempSync(join(tmpdir(), 'archon-forge-'));\n  const path = join(directory, 'request.json');\n  try {\n    writeFileSync(path, JSON.stringify(request), { mode: 0o600 });\n    const result = Bun.spawnSync([...command, 'forge', op, '--json', '--data-file', path], {\n      stdout: 'pipe',\n      stderr: 'pipe',\n    });\n    let parsed: unknown;\n    try {\n      parsed = JSON.parse(result.stdout.toString());\n    } catch {\n      const detail = result.stderr.toString().trim();\n      throw new Error(`forge ${op} failed${detail === '' ? '' : `: ${detail}`}`);\n    }\n    const response = record(parsed);\n    if (!response || typeof response.operationId !== 'string' || response.operationId === '') {\n      throw new Error(`forge ${op} returned an unexpected response envelope`);\n    }\n    // Exit 2 is the host saying it could not audit an operation that did complete.\n    // The response on stdout is the real outcome, so the result is still a result;\n    // losing it here would report a performed write as a failure.\n    if (response.ok === true && result.exitCode === 2) {\n      note(`forge ${op} completed but the host could not record it in the run's audit log.`);\n    } else if (response.ok !== true || result.exitCode !== 0) {\n      const mutation = record(response.mutation);\n      const error = record(response.error);\n      const outcome = typeof mutation?.outcome === 'string' ? mutation.outcome : undefined;\n      const message = typeof error?.message === 'string' ? error.message : 'operation failed';\n      throw new ForgeOperationError(\n        `forge ${op} ${outcome ?? 'failed'}: ${message}${mutation ? ` ${JSON.stringify(mutation)}` : ''}`,\n        mutation\n      );\n    }\n    const body = record(response.result);\n    if (body?.op !== op) throw new Error(`forge ${op} returned the wrong result`);\n    // A read may answer \"there is none\": `pr.view` by head returns null when the\n    // branch has no open pull request.\n    if (body.value === null) return null;\n    const value = record(body.value);\n    if (!value) throw new Error(`forge ${op} returned the wrong result`);\n    return value;\n  } finally {\n    rmSync(directory, { recursive: true, force: true });\n  }\n}\n\nfunction qualifiedRepo(value: unknown): QualifiedPr['repo'] | undefined {\n  const repo = record(value);\n  return typeof repo?.host === 'string' &&\n    repo.host.trim() !== '' &&\n    typeof repo.path === 'string' &&\n    repo.path.trim() !== ''\n    ? { host: repo.host, path: repo.path }\n    : undefined;\n}\n\n/** Validate only the pull-request facts this pack's policy consumes. */\nexport function parsePrRecord(value: unknown): PrRecord {\n  const pr = record(value);\n  const repo = qualifiedRepo(pr?.repo);\n  const headRepo = pr?.head_repo === null ? null : qualifiedRepo(pr?.head_repo);\n  const optionalText = (field: unknown): boolean =>\n    field === null || (typeof field === 'string' && field !== '');\n  if (\n    pr?.schemaVersion !== 1 ||\n    !repo ||\n    typeof pr.number !== 'number' ||\n    !Number.isInteger(pr.number) ||\n    pr.number <= 0 ||\n    typeof pr.url !== 'string' ||\n    !URL.canParse(pr.url) ||\n    typeof pr.head !== 'string' ||\n    pr.head === '' ||\n    typeof pr.base !== 'string' ||\n    pr.base === '' ||\n    typeof pr.is_draft !== 'boolean' ||\n    (pr.state !== 'open' && pr.state !== 'closed' && pr.state !== 'merged') ||\n    headRepo === undefined ||\n    !optionalText(pr.head_revision) ||\n    !optionalText(pr.base_revision) ||\n    !(typeof pr.maintainer_can_modify === 'boolean' || pr.maintainer_can_modify === null)\n  ) {\n    throw new Error('forge returned an invalid pull-request record');\n  }\n  return {\n    schemaVersion: 1,\n    repo,\n    number: pr.number,\n    url: pr.url,\n    head: pr.head,\n    base: pr.base,\n    is_draft: pr.is_draft,\n    state: pr.state,\n    head_repo: headRepo,\n    head_revision: pr.head_revision as string | null,\n    base_revision: pr.base_revision as string | null,\n    maintainer_can_modify: pr.maintainer_can_modify,\n  };\n}\n\nexport function parseQualifiedPr(value: string | undefined): QualifiedPr {\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(value ?? '');\n  } catch {\n    throw new Error('the bound pull request is not valid JSON');\n  }\n  const pr = record(parsed);\n  const repo = record(pr?.repo);\n  if (\n    typeof repo?.host !== 'string' ||\n    repo.host.trim() === '' ||\n    typeof repo.path !== 'string' ||\n    repo.path.trim() === '' ||\n    typeof pr?.number !== 'number' ||\n    !Number.isInteger(pr.number) ||\n    pr.number <= 0\n  ) {\n    throw new Error('the bound pull request has no qualified repo and positive number');\n  }\n  return { repo: { host: repo.host, path: repo.path }, number: pr.number };\n}\n\nfunction parseCommand(value: string | undefined): readonly string[] {\n  if (value === undefined || value === '') {\n    throw new Error(\n      'ARCHON_CLI_COMMAND is not set; the host that started this run did not publish its CLI command'\n    );\n  }\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(value ?? '');\n  } catch {\n    throw new Error('ARCHON_CLI_COMMAND is not a JSON string array');\n  }\n  if (\n    !Array.isArray(parsed) ||\n    parsed.length === 0 ||\n    !parsed.every(part => typeof part === 'string' && part !== '')\n  ) {\n    throw new Error('ARCHON_CLI_COMMAND must be a non-empty JSON string array');\n  }\n  return parsed as string[];\n}\n\nfunction parseUnit(value: unknown): CheckUnit | undefined {\n  const item = record(value);\n  const unit = record(item?.unit);\n  const states: readonly CheckState[] = CHECK_STATES.filter(state => state !== 'none');\n  const phases = ['pending', 'running', 'completed', 'unknown'] as const;\n  if (\n    typeof unit?.name !== 'string' ||\n    unit.name === '' ||\n    !states.includes(item?.state as CheckState) ||\n    !phases.includes(item?.phase as (typeof phases)[number]) ||\n    !(typeof item?.result === 'string' || item?.result === null)\n  )\n    return undefined;\n  return {\n    unit: { name: unit.name },\n    phase: item.phase as CheckUnit['phase'],\n    result: item.result,\n    state: item.state as CheckUnit['state'],\n  };\n}\n\nfunction parseSet(value: unknown): CheckSet | undefined {\n  const set = record(value);\n  const summary = record(set?.summary);\n  const states: readonly CheckState[] = CHECK_STATES;\n  if (!Array.isArray(set?.units) || !states.includes(summary?.state as CheckState))\n    return undefined;\n  const units = set.units.map(parseUnit);\n  if (units.some(unit => unit === undefined)) return undefined;\n  return { units: units as CheckUnit[], summary: { state: summary?.state as CheckState } };\n}\n\nfunction samePr(left: QualifiedPr, right: QualifiedPr): boolean {\n  return left.number === right.number && sameRepo(left.repo, right.repo);\n}\n\n/** Invoke `archon forge checks` and validate only the fields pack policy consumes. */\nexport function readChecks(ref: QualifiedPr): ChecksObservation {\n  const command = parseCommand(process.env.ARCHON_CLI_COMMAND);\n  const result = Bun.spawnSync(\n    [...command, 'forge', 'checks', '--json', '--data', JSON.stringify({ ref })],\n    {\n      stdout: 'pipe',\n      stderr: 'pipe',\n    }\n  );\n\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(result.stdout.toString());\n  } catch {\n    if (result.exitCode !== 0)\n      throw new Error(`forge check read failed: ${result.stderr.toString().trim()}`);\n    throw new Error('forge check read returned invalid JSON');\n  }\n  const response = record(parsed);\n  if (response?.ok === false) {\n    const error = record(response.error);\n    throw new Error(\n      `forge check read failed: ${typeof error?.message === 'string' ? error.message : 'unknown error'}`\n    );\n  }\n  if (result.exitCode !== 0) {\n    const detail = result.stderr.toString().trim();\n    throw new Error(`forge check read failed${detail === '' ? '' : `: ${detail}`}`);\n  }\n  const resultBody = record(response?.result);\n  const value = record(resultBody?.value);\n  const observedRef = record(value?.ref);\n  const observedRepo = record(observedRef?.repo);\n  const observed =\n    observedRepo && typeof observedRef?.number === 'number'\n      ? { repo: { host: observedRepo.host, path: observedRepo.path }, number: observedRef.number }\n      : undefined;\n  const full = parseSet(value);\n  const required = value?.required === null ? null : parseSet(value?.required);\n  if (\n    typeof response?.operationId !== 'string' ||\n    response.operationId === '' ||\n    response.ok !== true ||\n    resultBody?.op !== 'checks.state' ||\n    typeof value?.revision !== 'string' ||\n    value.revision === '' ||\n    !observed ||\n    typeof observed.repo.host !== 'string' ||\n    typeof observed.repo.path !== 'string' ||\n    !samePr(ref, observed as QualifiedPr) ||\n    !full ||\n    (value?.required !== null && !required)\n  ) {\n    throw new Error('forge check read returned an unexpected response shape or target');\n  }\n  return {\n    ref,\n    revision: value.revision,\n    units: full.units,\n    summary: full.summary,\n    required: required ?? null,\n  };\n}\n\nexport function preferredChecks(observation: ChecksObservation): CheckSet {\n  return observation.required ?? observation;\n}\n",".shared/io.ts":"/**\n * The process contract every deterministic script in this pack shares.\n *\n * A node's `with:` bindings arrive as `INPUTS_<UPPER_SNAKE>` environment text and\n * are always strings: a bound boolean arrives as `\"true\"`/`\"false\"`, and a skipped\n * producer bound with `if_skipped: null` arrives as `\"null\"`. Nothing here\n * interprets those spellings — what a value means belongs to the script that knows\n * what it is for.\n *\n * Read every binding as a literal `process.env.INPUTS_<NAME>` at its own call site\n * and pass the value in. The engine scans each script's source at workflow load and\n * refuses a workflow whose script reads a binding no `with:` clause or declared\n * input provides. It matches the literal form only, and it reads the entry script\n * alone, never its imports — so a helper that composed the key from a name would\n * hide every read in this pack from that check.\n *\n * Bun writes UTF-8 with `\\n` line endings on every platform, so a terminal report\n * composed here is byte-identical wherever a run happens. Nothing in this pack needs\n * to pin either by hand.\n */\n\n/**\n * Never call `process.exit()` in a packaged script.\n *\n * Bun 1.4.2 exits without draining stdout: a 500 KB write to a pipe arrives as\n * exactly 131072 bytes, silently. A truncated terminal report reads as a complete\n * one, and a truncated JSON document fails its node's certification with a message\n * about the schema rather than about the truncation. Setting `process.exitCode` and\n * returning lets the runtime flush before it leaves, which is why every helper here\n * sets the code instead of forcing the exit.\n */\nfunction setFailed(): void {\n  process.exitCode = 1;\n}\n\n/** A bound input's value, or the empty string when the binding is absent. */\nexport function text(value: string | undefined): string {\n  return value ?? '';\n}\n\n/** A bound input's value with surrounding whitespace removed. */\nexport function trimmed(value: string | undefined): string {\n  return (value ?? '').trim();\n}\n\n/**\n * This run's artifact directory.\n *\n * The engine supplies it to every exec node, so its absence is a bug in the engine\n * or in the node's declaration rather than a state a script should report on. This\n * throws instead of substituting a default that would read or write somewhere else.\n */\nexport function artifactsDir(): string {\n  const value = process.env.ARTIFACTS_DIR;\n  if (value === undefined || value === '') {\n    throw new Error('ARTIFACTS_DIR is not set; the engine supplies it to every exec node.');\n  }\n  return value;\n}\n\n/**\n * The node's result: one strict JSON document on stdout.\n *\n * A node that declares `output_format` gets exactly one attempt — no fence\n * stripping, no repair pass, no reask — so this is the only way a certified script\n * writes its result.\n */\nexport function emit(value: unknown): void {\n  console.log(JSON.stringify(value));\n}\n\n/** A plain-text result, for a node that declares no schema. */\nexport function report(value: string): void {\n  console.log(value);\n}\n\n/**\n * The node's refusal: the reason on stderr, a non-zero exit, nothing on stdout.\n *\n * The engine broadcasts stderr to the operator as the run happens and retains it on\n * the `node_failed` event, so the message is the whole diagnostic.\n */\nexport function refuse(message: string): void {\n  console.error(message);\n  setFailed();\n}\n\n/**\n * A note the operator should see from a node that is not failing.\n *\n * Stderr reaches the operator even on the success path, which is what keeps a gate\n * that deliberately passed red loud rather than silent.\n */\nexport function note(message: string): void {\n  console.error(message);\n}\n",".shared/node-env.ts":"/**\n * The environment an exec node receives from the engine as its run contract: where\n * this run keeps its artifacts, which run it is, and the node's bound inputs.\n *\n * A project command a node runs on the project's behalf, such as its test gate, is\n * not part of the run and must not see these. A gate that sees `WORKFLOW_ID` believes\n * it is inside the run, and any Archon command it starts then acts for that run.\n *\n * The engine owns the list as `EXEC_NODE_ENVIRONMENT_NAMES`. A pack script cannot\n * import engine code, so a conformance test beside the engine holds this copy to it.\n */\nexport const NODE_CONTRACT_ENV: readonly string[] = [\n  'ARTIFACTS_DIR',\n  'STATE_DIR',\n  'LOG_DIR',\n  'ADOPTED_RUN_DIR',\n  'WORKFLOW_ID',\n  'BASE_BRANCH',\n  'USER_MESSAGE',\n  'ARGUMENTS',\n  'LOOP_USER_INPUT',\n  'LOOP_PREV_OUTPUT',\n  'REJECTION_REASON',\n  'CONTEXT',\n  'EXTERNAL_CONTEXT',\n  'ISSUE_CONTEXT',\n  'TYPED_ARTIFACTS_FILE',\n  'ARCHON_NODE_EXECUTION',\n];\n\n/** A node's `with:` bindings arrive with this prefix. */\nconst BINDING_PREFIX = 'INPUTS_';\n\n/** The node's environment without the run contract: what a project command should see. */\nexport function projectEnvironment(env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {\n  const contract = new Set(NODE_CONTRACT_ENV);\n  return Object.fromEntries(\n    Object.entries(env).filter(([key]) => !contract.has(key) && !key.startsWith(BINDING_PREFIX))\n  );\n}\n",".shared/pr.ts":"/**\n * The pack's pull-request reads and writes, through whichever source the run\n * selected (./forge.ts).\n *\n * Every write here is performed and then read back before it is reported as\n * applied. On the forge path the plugin owns that verification and reports which\n * of the four outcomes happened; on `gh` this module performs the same read-back\n * and raises the failure itself. Neither path falls back to the other, and an\n * operation whose outcome could not be established is never retried here.\n *\n * Authored content — a pull-request body, a review report — is passed by file\n * path on both paths, so it never reaches any process's argv.\n */\n\nimport { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport {\n  invokeForge,\n  parsePrRecord,\n  record,\n  sameRepo,\n  type ForgeSource,\n  type PrRecord,\n  type QualifiedPr,\n} from './forge.ts';\n\nexport interface PrView {\n  readonly pr: PrRecord;\n  readonly title: string;\n  readonly body: string;\n}\n\nexport interface CreatePrIntent {\n  readonly repo: QualifiedPr['repo'];\n  readonly headRepo: QualifiedPr['repo'];\n  readonly head: string;\n  readonly headRevision: string;\n  readonly base: string;\n  readonly title: string;\n  readonly bodyPath: string;\n  readonly draft: boolean;\n}\n\ninterface Ran {\n  readonly ok: boolean;\n  readonly stdout: string;\n  readonly stderr: string;\n}\n\n// Every gh call is captured: a node's stderr reaches the operator, and gh is\n// chatty there (update notices), so only this pack's own messages may.\nfunction gh(...args: string[]): Ran {\n  const result = Bun.spawnSync(['gh', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  return {\n    ok: result.exitCode === 0,\n    stdout: result.stdout.toString().trim(),\n    stderr: result.stderr.toString().trim(),\n  };\n}\n\nfunction ghRepo(repo: QualifiedPr['repo']): string {\n  return `${repo.host}/${repo.path}`;\n}\n\nfunction required(result: Ran, what: string): string {\n  if (!result.ok) throw new Error(`${what} failed: ${result.stderr}`);\n  return result.stdout;\n}\n\nconst PR_FIELDS = [\n  'number',\n  'url',\n  'title',\n  'body',\n  'isDraft',\n  'state',\n  'baseRefName',\n  'headRefName',\n  'headRefOid',\n  'headRepository',\n  'headRepositoryOwner',\n  'maintainerCanModify',\n].join(',');\n\n/** One `gh pr view --json` row, narrowed to the fields this pack consumes. */\nfunction ghPrView(repo: QualifiedPr['repo'], value: unknown): PrView {\n  const row = record(value);\n  const headRepository = record(row?.headRepository);\n  const headOwner = record(row?.headRepositoryOwner);\n  const headPath =\n    typeof headRepository?.name === 'string' && typeof headOwner?.login === 'string'\n      ? `${headOwner.login}/${headRepository.name}`\n      : undefined;\n  const state = typeof row?.state === 'string' ? row.state.toLowerCase() : '';\n  return {\n    pr: parsePrRecord({\n      schemaVersion: 1,\n      repo,\n      number: row?.number,\n      url: row?.url,\n      head: row?.headRefName,\n      base: row?.baseRefName,\n      is_draft: row?.isDraft,\n      state,\n      head_repo: headPath === undefined ? null : { host: repo.host, path: headPath },\n      head_revision: typeof row?.headRefOid === 'string' && row.headRefOid !== '' ? row.headRefOid : null,\n      // gh does not report the base revision; the record keeps that absence explicit.\n      base_revision: null,\n      maintainer_can_modify:\n        typeof row?.maintainerCanModify === 'boolean' ? row.maintainerCanModify : null,\n    }),\n    title: typeof row?.title === 'string' ? row.title : '',\n    body: typeof row?.body === 'string' ? row.body : '',\n  };\n}\n\n/** A forge operation whose success always carries a result. */\nfunction forgeResult(op: string, request: Record<string, unknown>): Record<string, unknown> {\n  const value = invokeForge(op, request);\n  if (value === null) throw new Error(`forge ${op} returned no result`);\n  return value;\n}\n\nfunction forgePrView(value: Record<string, unknown>): PrView {\n  return {\n    pr: parsePrRecord(record(value)?.pr),\n    title: typeof value.title === 'string' ? value.title : '',\n    body: typeof value.body === 'string' ? value.body : '',\n  };\n}\n\n/**\n * The open pull request whose head is `headRepo:head` in `repo`, or undefined.\n *\n * \"Open\" is the question every caller here is actually asking: a branch that was\n * delivered and closed months ago must not stop a new pull request from opening,\n * and an open one must never be duplicated. More than one match is refused rather\n * than guessed at.\n */\nexport function findOpenPrByHead(\n  repo: QualifiedPr['repo'],\n  headRepo: QualifiedPr['repo'],\n  head: string,\n  source: ForgeSource\n): PrView | undefined {\n  if (source === 'forge') {\n    const value = invokeForge('pr.view', {\n      selector: { kind: 'head', repo, headRepo, head },\n    });\n    return value === null ? undefined : forgePrView(value);\n  }\n  const listed = gh(\n    'pr',\n    'list',\n    '--repo',\n    ghRepo(repo),\n    '--head',\n    head,\n    '--state',\n    'open',\n    '--json',\n    PR_FIELDS\n  );\n  const rows: unknown = JSON.parse(required(listed, 'gh pr list'));\n  if (!Array.isArray(rows)) throw new Error('gh pr list returned an unexpected payload');\n  // gh matches a head branch by name alone, so the qualified head repository is\n  // compared here; the forge selector already carries it.\n  const matches = rows\n    .map(row => ghPrView(repo, row))\n    .filter(view => view.pr.head_repo !== null && sameRepo(view.pr.head_repo, headRepo));\n  if (matches.length > 1) {\n    throw new Error(\n      `more than one open pull request in ${repo.path} has head ${headRepo.path}:${head}`\n    );\n  }\n  return matches[0];\n}\n\nexport function viewPr(ref: QualifiedPr, source: ForgeSource): PrView {\n  if (source === 'forge') {\n    const value = forgeResult('pr.view', {\n      selector: { kind: 'number', ref: { repo: ref.repo, number: ref.number } },\n    });\n    return forgePrView(value);\n  }\n  const result = gh(\n    'pr',\n    'view',\n    String(ref.number),\n    '--repo',\n    ghRepo(ref.repo),\n    '--json',\n    PR_FIELDS\n  );\n  return ghPrView(ref.repo, JSON.parse(required(result, `gh pr view ${String(ref.number)}`)));\n}\n\n/**\n * Open the pull request and return the record read back from the forge.\n *\n * A create that cannot be found again afterwards is reported as a pull request\n * that may exist, never as a failure that leaves the branch free to try again.\n */\nexport function createPr(intent: CreatePrIntent, source: ForgeSource): PrRecord {\n  if (source === 'forge') {\n    const value = forgeResult('pr.create', {\n      repo: intent.repo,\n      headRepo: intent.headRepo,\n      head: intent.head,\n      headRevision: intent.headRevision,\n      base: intent.base,\n      title: intent.title,\n      body: readFileSync(intent.bodyPath, 'utf8'),\n      draft: intent.draft,\n    });\n    return parsePrRecord(value.pr);\n  }\n  const body = readFileSync(intent.bodyPath, 'utf8');\n  const sameRepository = intent.headRepo.path === intent.repo.path;\n  const head = sameRepository ? intent.head : `${intent.headRepo.path.split('/')[0]}:${intent.head}`;\n  const created = gh(\n    'pr',\n    'create',\n    '--repo',\n    ghRepo(intent.repo),\n    '--base',\n    intent.base,\n    '--head',\n    head,\n    '--title',\n    intent.title,\n    '--body-file',\n    intent.bodyPath,\n    ...(intent.draft ? ['--draft'] : [])\n  );\n  if (!created.ok) throw new Error(`gh pr create failed: ${created.stderr}`);\n  const view = findOpenPrByHead(intent.repo, intent.headRepo, intent.head, source);\n  if (!view) {\n    throw new Error(\n      `gh pr create reported success but no open pull request has head ${intent.headRepo.path}:${intent.head}; a pull request may exist`\n    );\n  }\n  if (\n    view.title !== intent.title ||\n    view.body !== body ||\n    view.pr.head !== intent.head ||\n    view.pr.base !== intent.base ||\n    view.pr.head_revision !== intent.headRevision ||\n    view.pr.is_draft !== intent.draft ||\n    view.pr.state !== 'open'\n  ) {\n    throw new Error(\n      `the created pull request ${view.pr.url} does not match what was requested; it may need reconciling`\n    );\n  }\n  return view.pr;\n}\n\n/** Replace the pull request body, and prove the replacement landed. */\nexport function editPrBody(ref: QualifiedPr, bodyPath: string, source: ForgeSource): PrRecord {\n  const body = readFileSync(bodyPath, 'utf8');\n  if (source === 'forge') {\n    const value = forgeResult('pr.edit-body', {\n      ref: { repo: ref.repo, number: ref.number },\n      body,\n    });\n    return parsePrRecord(value.pr);\n  }\n  const number = String(ref.number);\n  const edited = gh('pr', 'edit', number, '--repo', ghRepo(ref.repo), '--body-file', bodyPath);\n  if (!edited.ok) throw new Error(`gh pr edit failed: ${edited.stderr}`);\n  const after = viewPr(ref, source);\n  if (after.body !== body) {\n    throw new Error(\n      `the pull request body read back from ${after.pr.url} does not match what was written; it may need reconciling`\n    );\n  }\n  return after.pr;\n}\n\n/** Take the pull request out of draft, and prove it is no longer a draft. */\nexport function markPrReady(ref: QualifiedPr, source: ForgeSource): PrRecord {\n  if (source === 'forge') {\n    const value = forgeResult('pr.ready', { ref: { repo: ref.repo, number: ref.number } });\n    return parsePrRecord(value.pr);\n  }\n  const ready = gh('pr', 'ready', String(ref.number), '--repo', ghRepo(ref.repo));\n  if (!ready.ok) throw new Error(`the ready flip failed: ${ready.stderr}`);\n  const after = viewPr(ref, source);\n  if (after.pr.is_draft || after.pr.state !== 'open') {\n    throw new Error(`${after.pr.url} still reports draft after the ready flip`);\n  }\n  return after.pr;\n}\n\ninterface GhComment {\n  readonly id: string;\n  readonly body: string;\n  readonly url: string;\n}\n\nfunction ghIssueComments(ref: QualifiedPr): GhComment[] {\n  const comments: GhComment[] = [];\n  // Paged explicitly rather than through `gh api --paginate`, so what this reads\n  // does not depend on how gh chooses to join pages of a JSON array.\n  for (let page = 1; ; page++) {\n    const result = gh(\n      'api',\n      '--hostname',\n      ref.repo.host,\n      `repos/${ref.repo.path}/issues/${String(ref.number)}/comments?per_page=100&page=${String(page)}`\n    );\n    const rows: unknown = JSON.parse(required(result, 'gh api issue comments'));\n    if (!Array.isArray(rows)) throw new Error('gh api returned an unexpected comment payload');\n    for (const row of rows) {\n      const comment = record(row);\n      if (\n        comment === undefined ||\n        (typeof comment.id !== 'number' && typeof comment.id !== 'string') ||\n        typeof comment.html_url !== 'string'\n      ) {\n        throw new Error('gh api returned an unexpected comment payload');\n      }\n      comments.push({\n        id: String(comment.id),\n        body: typeof comment.body === 'string' ? comment.body : '',\n        url: comment.html_url,\n      });\n    }\n    if (rows.length < 100) return comments;\n  }\n}\n\n/**\n * Write the one comment carrying `marker` on its first line, creating it if it is\n * not there yet and replacing it in place when it is. More than one marked\n * comment is a conflict: guessing which one is canonical would silently abandon\n * the other.\n */\nexport function upsertComment(\n  ref: QualifiedPr,\n  marker: string,\n  bodyPath: string,\n  source: ForgeSource\n): { readonly url: string } {\n  const body = readFileSync(bodyPath, 'utf8');\n  if (source === 'forge') {\n    const value = forgeResult('comment.upsert', {\n      ref: { repo: ref.repo, number: ref.number },\n      marker,\n      body,\n    });\n    const comment = record(value.comment);\n    if (typeof comment?.url !== 'string') throw new Error('forge returned no verified comment');\n    return { url: comment.url };\n  }\n  if ((body.split(/\\r?\\n/, 1)[0] ?? '') !== marker) {\n    throw new Error('the comment body must begin with the exact canonical marker');\n  }\n  const marked = ghIssueComments(ref).filter(\n    comment => (comment.body.split(/\\r?\\n/, 1)[0] ?? '') === marker\n  );\n  if (marked.length > 1) {\n    throw new Error('more than one comment on this pull request carries the canonical marker');\n  }\n  const previous = marked[0];\n  if (previous?.body === body) return { url: previous.url };\n  // gh reads the body from a JSON request file: `-f body=@path` would post the\n  // literal string, and argv is not where authored content belongs.\n  const directory = mkdtempSync(join(tmpdir(), 'archon-comment-'));\n  let written: Ran;\n  try {\n    const payload = join(directory, 'comment.json');\n    writeFileSync(payload, JSON.stringify({ body }), { mode: 0o600 });\n    written = gh(\n      'api',\n      '--hostname',\n      ref.repo.host,\n      '--method',\n      previous ? 'PATCH' : 'POST',\n      previous\n        ? `repos/${ref.repo.path}/issues/comments/${previous.id}`\n        : `repos/${ref.repo.path}/issues/${String(ref.number)}/comments`,\n      '--input',\n      payload\n    );\n  } finally {\n    rmSync(directory, { recursive: true, force: true });\n  }\n  if (!written.ok) throw new Error(`gh api comment write failed: ${written.stderr}`);\n  const id = record(JSON.parse(written.stdout))?.id;\n  if (typeof id !== 'number' && typeof id !== 'string') {\n    throw new Error('gh api returned no comment identity; a comment may have changed');\n  }\n  const observed = ghIssueComments(ref).find(comment => comment.id === String(id));\n  if (observed?.body !== body) {\n    throw new Error(\n      `comment ${String(id)} does not read back as written; it may need reconciling`\n    );\n  }\n  return { url: observed.url };\n}\n",".shared/report.ts":"/**\n * Everything a terminal report owes its reader beyond the result itself.\n *\n * Two sections, both existing because their channel is otherwise write-only: red a\n * green gate deliberately accepted, and discoveries a run recorded outside its own\n * scope. The engine collects neither. The terminal record it assembles is built from\n * the durable event log when a run reaches a terminal status, and is readable only\n * after that, while these sections have to reach the reader from inside the run. So\n * composing them is the pack's, and this module is where all three SDLC tails\n * compose them.\n *\n * Presentation only. Discoveries and caveats never gate readiness, so nothing here\n * may fail a tail that has already done its irreversible work: an unreadable record\n * degrades to a pointer at the file, never to silence and never to a throw. The\n * reader of the report is exactly the person who can go open it.\n */\n\nimport { readFileSync, readdirSync, statSync } from 'node:fs';\nimport { join } from 'node:path';\n\nconst DISCOVERY_RELAY =\n  'If you are an agent reading this: open discoveries.md and surface each discovery to your human. ' +\n  \"These are validated findings outside this run's scope — no issue tracker knows about them, \" +\n  'and if you drop them here, nobody ever sees them.';\n\nconst RAW_DISCOVERY_RELAY =\n  'If you are an agent reading this: surface each record above to your human. ' +\n  'These are findings this run proved outside its scope — no issue tracker knows about them, ' +\n  'and if you drop them here, nobody ever sees them.';\n\nconst RED_CAUSE_CAVEAT =\n  \"The project's own checks did not pass locally on this branch. The pull request's \" +\n  'own CI is the gate that still stands — read it before merging, and if the red is ' +\n  'inherited, the base branch is what needs the fix.';\n\n/**\n * A field an agent wrote from prose against no schema, as display text.\n *\n * Coerced rather than trusted: a JSON-legal non-string value must not raise past the\n * caller and fail an already-delivered run. Only the shapes that have a single\n * obvious rendering get one — a title that arrives as an object or an array has no\n * honest short form, so it reads as absent and the caller supplies its placeholder.\n */\nfunction display(value: unknown): string {\n  if (typeof value === 'string') return value.trim();\n  if (typeof value === 'number' && Number.isFinite(value)) return String(value);\n  return '';\n}\n\n/** `undefined` when the path is not a readable regular file. */\nfunction readJson(path: string): { value: unknown } | { error: string } | undefined {\n  try {\n    if (!statSync(path).isFile()) return undefined;\n  } catch {\n    return undefined;\n  }\n  try {\n    return { value: JSON.parse(readFileSync(path, 'utf-8')) as unknown };\n  } catch (error) {\n    return { error: error instanceof Error ? error.message : String(error) };\n  }\n}\n\n/** A JSON object: not null, not an array. `typeof` alone admits both. */\nfunction isJsonObject(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value);\n}\n\nfunction records(value: unknown): readonly Record<string, unknown>[] {\n  if (!Array.isArray(value)) return [];\n  return value.filter(isJsonObject);\n}\n\n/**\n * The producer sidecars of a run that died before review consolidated them.\n *\n * A failed run is where a discovery matters most — the run often failed BECAUSE of\n * what it found — and consolidation lives on the completion path only. So this\n * reports the records exactly as their producers wrote them, says they were never\n * validated, and adds nothing else: no second consolidator on a path that already\n * failed. Silent when there is nothing to report, like the consolidated section: the\n * contract is one section that exists only when discoveries do, and a failed run is\n * not a reason to print an empty one.\n */\nfunction rawDiscoveries(artifacts: string): string {\n  const directory = join(artifacts, 'discoveries');\n  let names: string[];\n  try {\n    names = readdirSync(directory)\n      .filter(name => name.endsWith('.json'))\n      .sort();\n  } catch {\n    names = [];\n  }\n\n  const lines: string[] = [];\n  const unreadable: string[] = [];\n  for (const name of names) {\n    const path = join(directory, name);\n    const read = readJson(path);\n    // The directory listing already said this entry is there, so \"not a readable\n    // regular file\" is a record this cannot show, never a record that is absent.\n    if (read === undefined) {\n      unreadable.push(`- ${path}: could not read (not a regular file). Open it directly.`);\n      continue;\n    }\n    if ('error' in read) {\n      unreadable.push(`- ${path}: could not read (${read.error}). Open it directly.`);\n      continue;\n    }\n    if (!Array.isArray(read.value)) {\n      unreadable.push(`- ${path}: not a JSON array of records. Open it directly.`);\n      continue;\n    }\n    for (const record of records(read.value)) {\n      const title = display(record.title) || '(untitled discovery)';\n      const relation = display(record.relation) || 'relation unstated';\n      const claim = display(record.claim);\n      lines.push(`- ${title} [${relation}]${claim ? `\\n  ${claim}` : ''}`);\n    }\n  }\n\n  if (lines.length === 0 && unreadable.length === 0) return '';\n  const body = [...lines, ...unreadable].join('\\n');\n  return (\n    `\\n\\nUnconsolidated discoveries (${lines.length}) — recorded by this run's nodes and ` +\n    `never validated or consolidated, because the run ended first:\\n${body}\\n\\n` +\n    `Raw records: ${directory}\\n\\n${RAW_DISCOVERY_RELAY}`\n  );\n}\n\n/**\n * The discoveries section, or empty when there is nothing to report.\n *\n * A FAILED run with no consolidated file never reached review, so the producers' own\n * sidecars are the entire record and `rawDiscoveries` owns that case. An EMPTY\n * consolidated file is review's adjudication rather than a gap, so it stays silent\n * and a completed run's report keeps the same shape on every branch.\n */\nfunction discoveries(artifacts: string, failed: boolean): string {\n  const path = join(artifacts, 'discoveries.json');\n  const read = readJson(path);\n  if (read === undefined) return failed ? rawDiscoveries(artifacts) : '';\n  if ('error' in read) {\n    return `\\n\\nDiscoveries: could not read ${path} (${read.error}). Open it directly.`;\n  }\n  if (!Array.isArray(read.value)) {\n    return `\\n\\nDiscoveries: ${path} is not a JSON array of records. Open it directly.`;\n  }\n  if (read.value.length === 0) return '';\n\n  const titles = read.value.map(entry => {\n    const record = records([entry])[0];\n    return (record === undefined ? '' : display(record.title)) || '(untitled discovery)';\n  });\n  const listed = titles.map(title => `- ${title}`).join('\\n');\n  return (\n    `\\n\\nDiscoveries (${read.value.length}):\\n${listed}\\n\\n` +\n    `Report: ${join(artifacts, 'discoveries.md')}\\n\\n${DISCOVERY_RELAY}`\n  );\n}\n\nfunction listedGates(\n  artifactsByType: unknown\n):\n  | { readonly gates: readonly Record<string, unknown>[] }\n  | { readonly limitation: string } {\n  if (!isJsonObject(artifactsByType)) {\n    return { limitation: 'its `artifactsByType` is not a JSON object' };\n  }\n  const gates = artifactsByType['green-gate'];\n  if (gates === undefined) return { gates: [] };\n  if (!Array.isArray(gates)) {\n    return { limitation: \"its `artifactsByType['green-gate']` is not an array\" };\n  }\n  const objects = gates.filter(isJsonObject);\n  if (objects.length !== gates.length) {\n    return { limitation: \"an `artifactsByType['green-gate']` entry is not a JSON object\" };\n  }\n  return { gates: objects };\n}\n\nfunction listingLimitation(message: string): string {\n  return (\n    `\\n\\nRed-cause disclosures could not be verified: ${message} ` +\n    'If a green gate accepted red, this report cannot show it.'\n  );\n}\n\n/**\n * The caveat for red this run's green gates deliberately let through.\n *\n * The engine hands every exec node a typed-artifact listing at\n * `TYPED_ARTIFACTS_FILE`: one JSON document naming the current run's readable\n * artifacts grouped by their exact `outputType`, each carrying the relative path of\n * its content, plus every record the engine could not read. Selecting\n * `artifactsByType['green-gate']` reads every gate that ran this run, loop\n * iterations included, with no directory walk and no filename guess; the engine has\n * already ordered them by production time. Lookup errors are shown here because a\n * corrupt sidecar could have been a gate, and it has no trustworthy type to hide\n * behind. A missing or unreadable listing is a named limitation, never silence: the\n * reader is exactly the person who can go open the run's records.\n */\nfunction redCauses(artifacts: string, listingFile: string | undefined): string {\n  if (listingFile === undefined || listingFile === '') {\n    return listingLimitation('no typed-artifact listing reached this node.');\n  }\n  const listing = readJson(listingFile);\n  if (listing === undefined) {\n    return listingLimitation(\n      `the typed-artifact listing ${listingFile} is not a readable regular file.`\n    );\n  }\n  if ('error' in listing) {\n    return listingLimitation(\n      `the typed-artifact listing ${listingFile} could not be read (${listing.error}).`\n    );\n  }\n  const envelope = records([listing.value])[0];\n  if (envelope === undefined) {\n    return listingLimitation(`the typed-artifact listing ${listingFile} is not a JSON object.`);\n  }\n\n  const reds: string[] = [];\n  const unreadable: string[] = [];\n  const gates = listedGates(envelope.artifactsByType);\n  if ('limitation' in gates) {\n    return listingLimitation(\n      `the typed-artifact listing ${listingFile} is malformed: ${gates.limitation}.`\n    );\n  }\n  for (const gate of gates.gates) {\n    const outputPath = join(artifacts, display(gate.path));\n    const body = readJson(outputPath);\n    if (body === undefined || 'error' in body) {\n      unreadable.push(`- ${outputPath}: could not read the gate's record. Open it directly.`);\n      continue;\n    }\n    const result = records([body.value])[0];\n    if (result === undefined) {\n      unreadable.push(`- ${outputPath}: not a gate record. Open it directly.`);\n      continue;\n    }\n    const cause = display(result.red_cause);\n    if (cause === '') continue;\n    const stage = display(result.stage) || 'A stage';\n    const summary = display(result.summary);\n    reds.push(`- ${stage}: ${cause} red${summary ? `\\n  ${summary}` : ''}`);\n  }\n\n  // Listing diagnostics name every record the engine could not turn into an\n  // artifact — including a gate whose sidecar or content it could not read. A\n  // present-but-non-array `errors` value is itself a shape failure, not silence.\n  const listingErrors = envelope.errors;\n  if (listingErrors !== undefined && !Array.isArray(listingErrors)) {\n    unreadable.push(\n      `- ${listingFile} (errors): the listing's \\`errors\\` value is not an array. ` +\n        'Its diagnostics cannot be read; open the listing directly.'\n    );\n  } else {\n    for (const error of records(listingErrors)) {\n      const path = display(error.path) || '(unknown record)';\n      const kind = display(error.kind) || 'unreadable';\n      const code = display(error.code);\n      unreadable.push(\n        `- ${path} (${kind}${code ? `, ${code}` : ''}): the engine could not read this record. ` +\n          'Open it directly.'\n      );\n    }\n  }\n\n  if (reds.length === 0 && unreadable.length === 0) return '';\n  return (\n    `\\n\\nDelivered on red (${reds.length}) — a gate accepted red this change did ` +\n    `not cause:\\n${[...reds, ...unreadable].join('\\n')}\\n\\n${RED_CAUSE_CAVEAT}`\n  );\n}\n\n/**\n * Both sections, composed in one place so that no branch of a tail's report can\n * print one and quietly drop the other. A caller that reached for the discovery\n * section alone would lose the red-cause caveat that makes passing red safe.\n * `listingFile` is passed in rather than read from the environment here, so the\n * reusable report never silently depends on ambient state.\n */\nexport function caveats(\n  artifacts: string,\n  options: { readonly failed: boolean; readonly listingFile: string | undefined }\n): string {\n  return redCauses(artifacts, options.listingFile) + discoveries(artifacts, options.failed);\n}\n",".shared/verdict.ts":"/**\n * The one judgment this pack makes about a red gate: whether the declared cause is\n * one the change cannot have introduced.\n *\n * The vocabulary itself (`introduced`, `inherited`, `environment`, `interaction`,\n * `incomplete`, or the empty string for \"not declared\") is an enum on the producing\n * nodes' `output_format`, where the engine certifies it. Nothing here re-checks\n * membership: a value that reaches a script through a `with:` binding already passed\n * that gate.\n */\n\nexport const PASSES_RED = ['inherited', 'environment'] as const;\n\n/** Red that the change did not cause: the base was already red, or the environment was. */\nexport function passesRed(cause: string): boolean {\n  return (PASSES_RED as readonly string[]).includes(cause);\n}\n\n/**\n * The refusal for a verdict declared `incomplete`: some checks never ran and none that\n * ran failed. It is not red, so it never says so — a reader sent hunting for a failure\n * that does not exist loses the real action, which is to let validation finish. Every\n * gate that reads a verdict refuses this cause with this one message.\n */\nexport function unfinishedValidation(stage: string, summary: string): string {\n  return (\n    `${stage}: validation didn't finish. Not every check ran, and none that ran ` +\n    `failed.${summary === '' ? '' : ` ${summary}`} Resume the run once whatever ` +\n    'stopped it is cleared, so validation can finish. An unfinished validation ' +\n    'never passes this gate.'\n  );\n}\n","deliver/scripts/check-ci.ts":"/**\n * Classify the recorded pull request's check state, once.\n *\n * This is the single-shot probe inside the `await-checks` loop_group: the engine's\n * durable `wait:` node owns the time between probes, so this script reads the state,\n * declares it, and exits. The checks come from the pack's one reader\n * (`.shared/checks.ts`): `gh` by default, `archon forge checks` when the operator\n * opts in with `ARCHON_SDLC_FORGE=forge`.\n *\n * States, declared through this node's `output_format` so `when:` and `until_bash`\n * branch on a certified field rather than on prose:\n *   pending    some check is still running\n *   concluded  green, no CI configured, or CI gated on a maintainer's approval (fork\n *              or first contribution) — a gate only a maintainer can open, named,\n *              never blocked on and never called green\n *   red        concluded with non-green checks, named. A cancelled or unrecognized\n *              check is not a green check.\n *\n * Red is a report, never a verdict: the deliver tail's convergence pass decides what\n * it means. A failed read refuses: it is never evidence that no CI exists.\n *\n * The one in-process wait: when nothing has registered yet, registration gets a\n * single 60 s grace before the maintainer-gated skip is declared. The gh source first\n * asks whether the repository has any active workflow, so a repository without CI\n * skips the wait.\n */\n\nimport {\n  atRevision,\n  describeUnits,\n  gateState,\n  hasActiveWorkflows,\n  readPrChecks,\n  type CheckRead,\n} from '../../.shared/checks.ts';\nimport { parseQualifiedPr } from '../../.shared/forge.ts';\nimport { emit, refuse } from '../../.shared/io.ts';\n\n/** The recorded pull request, so no read ever falls back to the ambient branch. */\nconst boundPr = process.env.INPUTS_PR;\nconst selected = process.env.ARCHON_SDLC_FORGE;\n\nfunction classify(read: CheckRead): void {\n  const at = atRevision(read);\n  const units = read.units;\n  switch (gateState(units)) {\n    case 'pending': {\n      const count = units.filter(unit => unit.state === 'pending').length;\n      emit({ state: 'pending', detail: `${count} check(s) running${at}` });\n      return;\n    }\n    case 'red': {\n      const parts: string[] = [];\n      const red = units.filter(unit => unit.state === 'red');\n      const unknown = units.filter(unit => unit.state === 'unknown');\n      if (red.length > 0) parts.push(`non-green checks${at}: ${describeUnits(red)}`);\n      if (unknown.length > 0) parts.push(`checks have unknown state${at}: ${describeUnits(unknown)}`);\n      emit({ state: 'red', detail: parts.join('; ') });\n      return;\n    }\n    case 'gated':\n      emit({\n        state: 'concluded',\n        detail: `checks gated${at}: ${describeUnits(units.filter(unit => unit.state === 'gated'))}`,\n      });\n      return;\n    case 'green': {\n      const skipped = units.filter(unit => unit.result === 'skipped');\n      const note =\n        skipped.length > 0\n          ? `; skipped (non-blocking): ${skipped.map(unit => unit.unit.name).join(', ')}`\n          : '';\n      emit({\n        state: 'concluded',\n        detail: `all ${units.length} observed check(s) green${at}${note}`,\n      });\n      return;\n    }\n    case 'none':\n      return;\n  }\n}\n\nfunction probe(): void {\n  const pr = parseQualifiedPr(boundPr);\n  const first = readPrChecks(pr, selected);\n  if (first.units.length > 0) {\n    classify(first);\n    return;\n  }\n  if (first.source === 'gh' && hasActiveWorkflows(pr) === false) {\n    emit({ state: 'concluded', detail: 'no checks configured on this repository — nothing to await' });\n    return;\n  }\n  // CI exists (or could not be ruled out) but nothing started. Give registration one\n  // grace interval, then skip with the reason: starting gated CI is a maintainer's\n  // power, not this run's.\n  Bun.sleepSync(60_000);\n  const second = readPrChecks(pr, selected);\n  if (second.units.length > 0) {\n    classify(second);\n    return;\n  }\n  emit({\n    state: 'concluded',\n    detail:\n      `CI is configured but no checks started on this PR${atRevision(second)} — most likely ` +\n      \"awaiting a maintainer's approval to run (fork or first contribution), or path \" +\n      'filters. Skipping the CI gate; running and verifying checks stays with the maintainer.',\n  });\n}\n\ntry {\n  probe();\n} catch (error) {\n  refuse(`check-ci: ${error instanceof Error ? error.message : String(error)}`);\n}\n","deliver/scripts/ci-attention-route.ts":"/** Route non-introduced late CI red to an explicit operator action. */\n\nimport { emit, trimmed } from '../../.shared/io.ts';\nimport { passesRed } from '../../.shared/verdict.ts';\n\nconst redCause = trimmed(process.env.INPUTS_RED_CAUSE);\nemit({ attention: passesRed(redCause), red_cause: redCause });\n","deliver/scripts/ci-note.ts":"/**\n * CI evidence for one correction round, read once and never waited on.\n *\n * The note is advisory: a round proceeds on its review findings when no evidence\n * is available. A failed read still reaches the operator on stderr, so a selected\n * check source that cannot answer is visible here before `check-ci` refuses on it.\n */\n\nimport { atRevision, describeUnits, readPrChecks } from '../../.shared/checks.ts';\nimport { parseQualifiedPr } from '../../.shared/forge.ts';\nimport { note, report } from '../../.shared/io.ts';\n\nconst boundPr = process.env.INPUTS_PR;\nconst selected = process.env.ARCHON_SDLC_FORGE;\n\ntry {\n  const read = readPrChecks(parseQualifiedPr(boundPr), selected);\n  if (read.units.length === 0) {\n    report(\n      'No CI evidence is available for this round (no checks reported). Proceed on the review findings alone.'\n    );\n  } else {\n    const failing = read.units.filter(unit => unit.state === 'red' || unit.state === 'unknown');\n    const pending = read.units.filter(unit => unit.state === 'pending');\n    const gated = read.units.filter(unit => unit.state === 'gated');\n    const lines = [\n      `CI state for this pull request${atRevision(read)}, read at the start of this round; it describes the currently pushed head:`,\n      failing.length > 0\n        ? `Concluded non-green checks:\\n${failing.map(unit => `- ${unit.unit.name} (${unit.result ?? unit.state})`).join('\\n')}`\n        : 'No concluded failures.',\n    ];\n    if (pending.length > 0)\n      lines.push(`${pending.length} check(s) still running — never wait on them.`);\n    if (gated.length > 0) lines.push(`Gated on a maintainer: ${describeUnits(gated)}.`);\n    report(lines.join('\\n'));\n  }\n} catch (error) {\n  note(`ci-note: ${error instanceof Error ? error.message : String(error)}`);\n  report(\n    'No CI evidence is available for this round (the check read failed). Proceed on the review findings alone.'\n  );\n}\n","deliver/scripts/ci-round-result.ts":"/**\n * Carry the late-CI round's two facts out of its loop as one value: the recheck's\n * action and the fix's declared red cause. Both were certified where they were\n * produced; this only puts them side by side for the loop's `until` and the route\n * after it.\n */\n\nimport { emit, text, trimmed } from '../../.shared/io.ts';\n\nemit({\n  action: text(process.env.INPUTS_ACTION),\n  red_cause: trimmed(process.env.INPUTS_RED_CAUSE),\n});\n","deliver/scripts/flip-ready.ts":"/**\n * The ready flip: the one irreversible step, so it re-verifies CI itself instead of\n * trusting the loop above. It reads through the pack's check reader (`gh` by\n * default, `archon forge checks` with `ARCHON_SDLC_FORGE=forge`) and refuses any\n * pending, red, gated or unknown check, and any failed read: a failed observation\n * is not evidence that no CI exists. Both the read and the flip target the recorded\n * qualified pull request, never the checkout's remote, and both go through the\n * source the run selected.\n *\n * A pull request that is already merged needs no flip and is reported as such; one\n * that is closed without a merge has no delivery to report and refuses.\n */\nimport { atRevision, describeUnits, gateState, readPrChecks } from '../../.shared/checks.ts';\nimport { forgeSource, parseQualifiedPr, type QualifiedPr } from '../../.shared/forge.ts';\nimport { markPrReady, viewPr } from '../../.shared/pr.ts';\nimport { emit, note, refuse } from '../../.shared/io.ts';\n\nconst boundPr = process.env.INPUTS_PR;\nconst selected = process.env.ARCHON_SDLC_FORGE;\n\nfunction preflight(): QualifiedPr | undefined {\n  try {\n    const pr = parseQualifiedPr(boundPr);\n    const read = readPrChecks(pr, selected);\n    const state = gateState(read.units);\n    if (state !== 'green' && state !== 'none') {\n      const notGreen = read.units.filter(unit => unit.state !== 'green');\n      throw new Error(\n        `refusing to flip with ${state} checks${atRevision(read)}: ${describeUnits(notGreen)}`\n      );\n    }\n    return pr;\n  } catch (error) {\n    refuse(`flip-ready: ${error instanceof Error ? error.message : String(error)}`);\n    return undefined;\n  }\n}\n\nfunction flipReady(): void {\n  const pr = preflight();\n  if (pr === undefined) return;\n  try {\n    const source = forgeSource(selected);\n    const observed = viewPr(pr, source).pr;\n    if (observed.state === 'merged') {\n      note('flip-ready: the PR was already merged, so no flip was needed.');\n      emit({ pr_url: observed.url });\n      return;\n    }\n    if (observed.state === 'closed') {\n      refuse('flip-ready: the PR is CLOSED without a merge, so there is no delivery to report.');\n      return;\n    }\n    emit({ pr_url: observed.is_draft ? markPrReady(pr, source).url : observed.url });\n  } catch (error) {\n    refuse(`flip-ready: ${error instanceof Error ? error.message : String(error)}`);\n  }\n}\nflipReady();\n","deliver/scripts/gate-green.ts":"/**\n * The green gate: run success never certifies green — this does, deterministically.\n *\n * The delivery tail asks the question after implementation, after corrections, and\n * after the project's own full gate runs post-review. The same script answers it each\n * time. A node that produced a verdict is not a node that passed; the loop completes\n * on `done`, blocked declines included, so no spend and no public step happens until\n * this reads the verdict itself.\n *\n * Red is not one thing, though, and treating it as one killed two correct deliveries.\n * A change that breaks a check must never reach a pull request. A check that was\n * already red at the run's starting commit, or that failed because a parallel process\n * held the database this run needed, is not evidence about the change at all — and\n * reality gets checked again downstream regardless: flip-ready refuses to make the PR\n * ready while its real CI is not green. So this fails on `introduced` and lets\n * `inherited` and `environment` through with the claim recorded.\n *\n * A validation that did not finish is not red at all: `incomplete` means some checks\n * never ran and none that ran failed. It fails too, since an unfinished gate is no\n * verdict, but it says so and names resuming the run as the action.\n *\n * The record is this node's own result. Its node declares `output_type: green-gate`,\n * so the engine keeps the JSON below as a typed artifact under `nodes/`, one file per\n * gate, and every later reader — the pull-request body, the terminal report — finds\n * the passed reds by type. No shared file, so no gate ever overwrites or races\n * another's record.\n *\n * `green` and `red_cause` arrive certified: the producing node's `output_format`\n * declares the boolean and the enum, and the engine enforces both before the value\n * is bound here. The evidence behind the claim belongs to that node's prompt and\n * its report; this reads only that some evidence was given.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_GREEN: the declaring node's verdict, canonical boolean text.\n * - INPUTS_RED_CAUSE: the declared cause, or '' when the field was absent.\n * - INPUTS_SUMMARY: that node's summary, which carries the evidence for the claim.\n * - INPUTS_STAGE: which gate this is, for the record a human reads later.\n */\n\nimport { emit, note, refuse, trimmed } from '../../.shared/io.ts';\nimport { passesRed, unfinishedValidation } from '../../.shared/verdict.ts';\n\nconst green = trimmed(process.env.INPUTS_GREEN);\nconst cause = trimmed(process.env.INPUTS_RED_CAUSE);\nconst summary = trimmed(process.env.INPUTS_SUMMARY);\nconst stage = trimmed(process.env.INPUTS_STAGE) || 'The work';\n\nif (cause === 'incomplete') {\n  // Decided before `green` is read, because a green over checks that never ran is\n  // unsupported.\n  refuse(unfinishedValidation(stage, summary));\n} else if (green === 'true') {\n  emit({ gate: 'green', red_cause: '', stage, summary: '' });\n} else if (cause === '') {\n  refuse(\n    `${stage} is red and declared no red_cause. Red that nobody explained is red this ` +\n      'gate refuses — its summary says what happened.'\n  );\n} else if (!passesRed(cause)) {\n  refuse(\n    `${stage} is red (${cause}). ` +\n      (cause === 'interaction'\n        ? `The separately green changes fail when composed; hold this combination. ${summary} `\n        : 'The change has no accepted non-introduced-red evidence. ') +\n      'Refusing to open or advance a pull request on red work.'\n  );\n} else if (summary === '') {\n  // The label is not the claim. A pass on non-introduced red is worth exactly the\n  // evidence behind it — the failing check named, and why this change cannot have\n  // caused it — and an empty summary carries none. Emptiness is all this checks;\n  // whether the prose is genuine evidence is the declaring agent's judgment and the\n  // reviewer's, never something to reconstruct from the text.\n  refuse(\n    `${stage} declared its red ${cause}, but recorded no evidence for the claim. ` +\n      'A pass on red the change did not cause is only as good as the failing check ' +\n      'it names — refusing without it.'\n  );\n} else {\n  note(\n    `${stage} is red, and declared that red ${cause} rather than introduced. ` +\n      \"Proceeding so the pull request's own CI can be observed; a red conclusion \" +\n      'requires explicit operator action.'\n  );\n  emit({ gate: 'green', red_cause: cause, stage, summary });\n}\n","deliver/scripts/gate-ready.ts":"/**\n * Deterministic readiness join: certifies the review verdict before validate and\n * flip spend.\n *\n * Two actions arrive through `with:` bindings, no latch files: the initial review's,\n * and the correction loop's final one — null when the loop was skipped. Both are\n * enum values the engine certified on the node that produced them, so this reads\n * them as facts and decides.\n *\n * The correction loop completes for either `none` or `replan`; only `none` is ready.\n * A replan fails here with the draft PR and the canonical report intact, which is why\n * the loop's own completion cannot be the gate.\n */\n\nimport { refuse, report, text } from '../../.shared/io.ts';\n\nconst reviewAction = text(process.env.INPUTS_REVIEW_ACTION);\nconst correctionAction = text(process.env.INPUTS_CORRECTION_ACTION) || 'null';\n\nif (reviewAction === 'none' || (reviewAction === 'correct' && correctionAction === 'none')) {\n  report('{\"ready\":\"true\"}');\n} else if (reviewAction === 'replan' || correctionAction === 'replan') {\n  refuse(\n    'replan required: the review proved that the requested outcome cannot be ' +\n      'completed inside the accepted work order. The pull request remains draft; ' +\n      'see the canonical review report and discovery artifacts.'\n  );\n} else {\n  refuse(\n    'not ready: no validated ready verdict reached the delivery gate -- see the ' +\n      'earliest failed or skipped node, the review report in the run artifacts, ' +\n      'and the canonical PR comment.'\n  );\n}\n","deliver/scripts/outcome.ts":"/**\n * The delivery tail's terminal report.\n *\n * flip-ready owns the one irreversible public action and certifies the ready pull\n * request's URL as its declared result. This composes what the run's reader — usually\n * an orchestrating agent — actually receives, which is that URL plus whatever the\n * review recorded in the run's discovery sidecar.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_PR_URL: `$flip-ready.output.pr_url`, certified non-empty at the producer.\n */\n\nimport { artifactsDir, emit, refuse, trimmed } from '../../.shared/io.ts';\nimport { caveats } from '../../.shared/report.ts';\n\nconst artifacts = artifactsDir();\nconst listingFile = process.env.TYPED_ARTIFACTS_FILE;\nconst url = trimmed(process.env.INPUTS_PR_URL);\n\nif (url === '') {\n  refuse(\n    `outcome: flip-ready reported no pull request URL.${caveats(artifacts, { failed: true, listingFile })}`\n  );\n} else {\n  emit({\n    pr_url: url,\n    summary: `${url}${caveats(artifacts, { failed: false, listingFile })}`,\n  });\n}\n","deliver/scripts/publish-pr-body.ts":"/**\n * Publish the resynced pull-request body.\n *\n * The preceding node judges which claims the final diff falsified and writes the\n * complete replacement body; this node performs the edit and verifies it, or\n * reports that the body was already accurate and nothing was written.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_PR: `$pr.output`, the run's verified pull-request record.\n * - INPUTS_INTENT: path to the JSON intent the preparing node wrote.\n */\n\nimport { readFileSync } from 'node:fs';\nimport { editPrBody } from '../../.shared/pr.ts';\nimport { forgeSource, parsePrRecord, record } from '../../.shared/forge.ts';\nimport { emit, refuse, text } from '../../.shared/io.ts';\n\ntry {\n  const source = forgeSource(process.env.ARCHON_SDLC_FORGE);\n  const pr = parsePrRecord(JSON.parse(text(process.env.INPUTS_PR)));\n  const intent = record(JSON.parse(readFileSync(text(process.env.INPUTS_INTENT), 'utf8')));\n  if (!intent) throw new Error('the body intent must be a JSON object');\n  if (intent.change === false) emit(pr);\n  else if (intent.change !== true || typeof intent.bodyPath !== 'string' || intent.bodyPath === '')\n    throw new Error('the body intent must declare change true with a bodyPath, or change false');\n  else emit(editPrBody(pr, intent.bodyPath, source));\n} catch (error) {\n  refuse(`publish-pr-body: ${error instanceof Error ? error.message : String(error)}`);\n}\n","deliver/scripts/read-pr-body.ts":"/**\n * Read the recorded pull request's current description for the resync node.\n *\n * The body is read from the forge rather than from what this run wrote when the\n * pull request opened: a human may have edited it since, and a resync that\n * silently reverted that edit would be a write nobody asked for. Reading it here\n * also keeps the authoring node free of the source switch.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_PR: `$pr.output`, the run's verified pull-request record.\n */\n\nimport { join } from 'node:path';\nimport { writeFileSync } from 'node:fs';\nimport { viewPr } from '../../.shared/pr.ts';\nimport { forgeSource, parsePrRecord } from '../../.shared/forge.ts';\nimport { artifactsDir, emit, refuse, text } from '../../.shared/io.ts';\n\ntry {\n  const source = forgeSource(process.env.ARCHON_SDLC_FORGE);\n  const pr = parsePrRecord(JSON.parse(text(process.env.INPUTS_PR)));\n  const view = viewPr(pr, source);\n  const path = join(artifactsDir(), 'pr-body-current.md');\n  writeFileSync(path, view.body);\n  emit({ body: path, url: view.pr.url });\n} catch (error) {\n  refuse(`read-pr-body: ${error instanceof Error ? error.message : String(error)}`);\n}\n","deliver/scripts/resolve-review-scope.ts":"/**\n * Resolve the operator's review-lens override against the classifier's judgment.\n *\n * A declared `true`/`false` beats the classifier; `auto` — or anything else the\n * operator did not declare — adopts its judgment. The values below are the strings\n * the lens gate compares against, not booleans: they travel on as a composed\n * workflow's `errors` input, which is declared text.\n *\n * The docs lens is deliberately absent. It reads the classifier's verdict directly,\n * because it has no operator override to merge over.\n */\n\nimport { emit, refuse, text } from '../../.shared/io.ts';\n\ntype Verdict = 'true' | 'false';\n\nfunction isVerdict(value: string): value is Verdict {\n  return value === 'true' || value === 'false';\n}\n\nconst forced = text(process.env.INPUTS_ERRORS);\nconst judged = text(process.env.INPUTS_C_ERRORS);\n\nif (isVerdict(forced)) {\n  emit({ errors: forced });\n} else if (!isVerdict(judged)) {\n  refuse(`resolve-review-scope: classifier returned an invalid errors verdict: '${judged}'`);\n} else {\n  emit({ errors: judged });\n}\n","implement/scripts/assert-changed.ts":"/**\n * Deterministic guard: did this implement invocation produce work?\n *\n * An AI node that declines its task still exits 0, so without this check the stages\n * after implement would spend money or go public on nothing. It reads Archon-owned\n * facts only -- the engine's checkout observations and git objects -- never the\n * project's layout or toolchain.\n *\n * Three ways to pass, in order:\n * 1. New content: some path's content, mode, or type differs from where THIS implement\n *    invocation started (outside `.archon/`; see below). The start is the engine's own\n *    observation of the implement node's invocation, bound as `baseline`. Changes that\n *    were already in the checkout when it started are part of that start, so a dirty\n *    checkout the loop never touched does not pass. HEAD moving, staging, or an empty\n *    commit changes no content and does not pass either.\n * 2. Verified existing work: no new content, but the loop declared green AND the branch\n *    already carries commits ahead of the base branch -- a rerun that verified a fix a\n *    prior run committed is progress, not a decline.\n * 3. An honest decline on red the change did not cause: no new content, the loop is not\n *    green, and it declared that red `inherited` or `environment` with evidence in its\n *    summary. A correction round can genuinely have nothing left to edit -- the\n *    remaining break is in the base, or in configuration the run has no permission to\n *    change -- and demanding a change anyway asks for an invented one, or throws away\n *    the rounds that already landed. What such a claim is worth is the green gates'\n *    question, not this one; the tolerance lives here only so a change that cannot\n *    exist stops being required.\n *\n * Red the loop introduced still fails with nothing to show, and so does red it left\n * unexplained or unevidenced -- the same bar the green gates hold, because a cause\n * with no failing check named behind it is not a reason. A green claim with neither\n * new content nor a branch lead fails too.\n *\n * A loop that ended with its checks unfinished (`incomplete`) fails before any of\n * that is asked, whatever it changed: its work was never verified, and the green\n * gates refuse the same cause with the same message.\n *\n * Only UNCOMMITTED `.archon/` changes are excluded: Archon copies the operator's\n * workflow edits into every run worktree, so uncommitted `.archon/` files are not\n * implement's output. A `.archon/` path counts only when the current commit differs\n * from the start commit and the committed content differs from what the path held at\n * the start -- implement legitimately edits workflows, but committing bytes that were\n * already sitting in the checkout is not new work.\n *\n * Comparison: the engine records a start commit plus a manifest of only the paths that\n * differed from it, each identified by Git's blob id of its bytes (`hash-object`, clean\n * conversion applied), mode, and type. For every path that differs now or differed at\n * the start, the current identity (this node's own start observation, or the current\n * commit's tree) is compared with the starting identity (the start manifest, or the\n * start commit's tree). An observation that could not identify every path cannot prove\n * new work, and neither can a start that is not a Git checkout.\n */\n\nimport { createHash } from 'node:crypto';\nimport { readFileSync } from 'node:fs';\nimport { isAbsolute, join } from 'node:path';\nimport { artifactsDir, refuse, report, trimmed } from '../../.shared/io.ts';\nimport { PASSES_RED, passesRed, unfinishedValidation } from '../../.shared/verdict.ts';\n\n/** A git read whose failure is a broken assumption, not a state to report on. */\nfunction gitBytes(...args: string[]): Buffer {\n  const result = Bun.spawnSync(['git', '--literal-pathspecs', ...args], {\n    stdout: 'pipe',\n    stderr: 'pipe',\n  });\n  if (result.exitCode !== 0) {\n    throw new Error(`git ${args[0] ?? ''} failed: ${result.stderr.toString().trim()}`);\n  }\n  return result.stdout;\n}\n\n/** `undefined` when the ref does not resolve, which is an answer rather than a fault. */\nfunction tryGit(...args: string[]): string | undefined {\n  const result = Bun.spawnSync(['git', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  return result.exitCode === 0 ? result.stdout.toString().trim() : undefined;\n}\n\n/** Commits this branch carries beyond the base, or `undefined` if neither ref resolves. */\nfunction commitsAheadOfBase(base: string): { readonly ref: string; readonly ahead: number } | undefined {\n  for (const ref of [`origin/${base}`, base]) {\n    const ahead = tryGit('rev-list', '--count', `${ref}..HEAD`);\n    if (ahead !== undefined) return { ref, ahead: Number.parseInt(ahead, 10) };\n  }\n  return undefined;\n}\n\n// --- The engine's checkout observation, as this consumer reads it --------------------\n//\n// The owning contract is the engine's `CheckoutObservation` schema. This pack cannot\n// import engine code, so it reads only the fields it needs and rejects anything else\n// as unreadable; a conformance test in the engine feeds real observations through this\n// script so the two cannot drift silently.\n\n/** A path's identity: absent, or a kind/mode/object id. Equality is identity. */\ntype Identity = { readonly kind: 'absent' } | { readonly kind: string; readonly mode: string; readonly oid: string };\n\ninterface Observed {\n  readonly commit: string | null;\n  /** Paths that differed from `commit` when sampled, keyed by raw path bytes (base64). */\n  readonly dirty: ReadonlyMap<string, Identity>;\n}\n\ntype Reading = { readonly observed: Observed } | { readonly unknown: string };\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value);\n}\n\nfunction pathKey(path: unknown): string | undefined {\n  if (typeof path === 'string') return Buffer.from(path, 'utf8').toString('base64');\n  if (isRecord(path) && typeof path.base64 === 'string') return path.base64;\n  return undefined;\n}\n\nfunction readObservation(label: string, value: unknown, runId: string): Reading {\n  if (!isRecord(value)) return { unknown: `${label} is not a checkout observation` };\n  if (value.kind === 'not_git') return { unknown: `${label} was not a Git checkout` };\n  if (value.kind === 'unavailable') {\n    return { unknown: `${label} could not be observed (${String(value.reason)})` };\n  }\n  if (value.kind !== 'git' || !isRecord(value.worktree)) {\n    return { unknown: `${label} is not a checkout observation this guard can read` };\n  }\n  const commit = value.commit;\n  if (commit !== null && typeof commit !== 'string') return { unknown: `${label} has no commit` };\n  const worktree = value.worktree;\n  if (worktree.status === 'clean') return { observed: { commit, dirty: new Map() } };\n  if (worktree.status !== 'dirty' || !isRecord(worktree.manifest)) {\n    return { unknown: `${label} has an unreadable worktree state` };\n  }\n  const pointer = worktree.manifest.pointer;\n  const digest = worktree.manifest.sha256;\n  if (!isRecord(pointer) || typeof pointer.path !== 'string' || typeof digest !== 'string') {\n    return { unknown: `${label} has no manifest reference` };\n  }\n  if (pointer.run_id !== runId) return { unknown: `${label} points at another run's manifest` };\n  if (isAbsolute(pointer.path) || pointer.path.split(/[\\\\/]/).includes('..')) {\n    return { unknown: `${label} has an unsafe manifest path` };\n  }\n  let bytes: Buffer;\n  try {\n    bytes = readFileSync(join(artifactsDir(), pointer.path));\n  } catch {\n    return { unknown: `${label}'s manifest is missing` };\n  }\n  if (createHash('sha256').update(bytes).digest('hex') !== digest) {\n    return { unknown: `${label}'s manifest does not match its recorded digest` };\n  }\n  let manifest: unknown;\n  try {\n    manifest = JSON.parse(bytes.toString('utf8'));\n  } catch {\n    return { unknown: `${label}'s manifest is not JSON` };\n  }\n  if (!isRecord(manifest) || manifest.version !== 1 || !Array.isArray(manifest.entries)) {\n    return { unknown: `${label}'s manifest has an unknown format` };\n  }\n  if (manifest.commit !== commit) return { unknown: `${label}'s manifest names another commit` };\n  const dirty = new Map<string, Identity>();\n  for (const entry of manifest.entries) {\n    if (!isRecord(entry)) return { unknown: `${label}'s manifest has a malformed entry` };\n    const key = pathKey(entry.path);\n    if (key === undefined) return { unknown: `${label}'s manifest has a malformed path` };\n    if (entry.kind === 'absent') {\n      dirty.set(key, { kind: 'absent' });\n    } else if ((entry.kind === 'file' || entry.kind === 'symlink') && typeof entry.blob === 'string') {\n      dirty.set(key, { kind: entry.kind, mode: String(entry.mode), oid: entry.blob });\n    } else if (entry.kind === 'gitlink' && typeof entry.commit === 'string') {\n      dirty.set(key, { kind: 'gitlink', mode: '160000', oid: entry.commit });\n    } else {\n      return { unknown: `${label} could not identify every changed path` };\n    }\n  }\n  return { observed: { commit, dirty } };\n}\n\n// --- Commit-side identities -----------------------------------------------------------\n\n/** NUL-separated raw records. */\nfunction splitNul(output: Buffer): Buffer[] {\n  const records: Buffer[] = [];\n  let start = 0;\n  while (start < output.length) {\n    const end = output.indexOf(0, start);\n    const stop = end === -1 ? output.length : end;\n    if (stop > start) records.push(output.subarray(start, stop));\n    start = stop + 1;\n  }\n  return records;\n}\n\n/** Paths whose tree entries differ between two commits (or every path of one). */\nfunction committedPaths(from: string | null, to: string | null): string[] {\n  if (from === to) return [];\n  let listing: Buffer;\n  if (from !== null && to !== null) {\n    listing = gitBytes('diff-tree', '-r', '-z', '--no-renames', '--name-only', from, to);\n  } else {\n    // One side is an unborn branch: every path of the other commit differs.\n    const only = from ?? to;\n    if (only === null) return [];\n    listing = gitBytes('ls-tree', '-r', '-z', '--name-only', only);\n  }\n  return splitNul(listing).map(path => path.toString('base64'));\n}\n\n/** Tree identities of the given paths in one commit; paths the tree lacks are absent. */\nfunction treeIdentities(commit: string | null, keys: readonly string[]): Map<string, Identity> {\n  const identities = new Map<string, Identity>(keys.map(key => [key, { kind: 'absent' }]));\n  if (commit === null || keys.length === 0) return identities;\n  // argv carries UTF-8 text; a non-UTF-8 path cannot be named there, so it cannot be\n  // looked up and stays absent -- the observation already refused to identify such a\n  // path as dirty, which keeps this from ever deciding equality on it.\n  const names = keys\n    .map(key => Buffer.from(key, 'base64'))\n    .filter(raw => Buffer.from(raw.toString('utf8'), 'utf8').equals(raw))\n    .map(raw => raw.toString('utf8'));\n  for (let i = 0; i < names.length; i += 200) {\n    const listing = gitBytes('ls-tree', '-r', '-z', commit, '--', ...names.slice(i, i + 200));\n    for (const record of splitNul(listing)) {\n      // \"<mode> <type> <oid>\\t<path>\"\n      const tab = record.indexOf(0x09);\n      const [mode = '', type = '', oid = ''] = record.subarray(0, tab).toString('latin1').split(' ');\n      const key = record.subarray(tab + 1).toString('base64');\n      if (!identities.has(key)) continue;\n      identities.set(key, {\n        kind: type === 'commit' ? 'gitlink' : mode === '120000' ? 'symlink' : 'file',\n        mode,\n        oid,\n      });\n    }\n  }\n  return identities;\n}\n\nfunction same(a: Identity | undefined, b: Identity | undefined): boolean {\n  if (a === undefined || b === undefined) return false;\n  if (!('oid' in a) || !('oid' in b)) return !('oid' in a) && !('oid' in b);\n  return a.kind === b.kind && a.mode === b.mode && a.oid === b.oid;\n}\n\nconst ARCHON_DIR = Buffer.from('.archon/', 'utf8');\n\n/** How many paths' content differs from where the invocation started. */\nfunction contentChanges(baseline: Observed, current: Observed): number {\n  const keys = new Set<string>([\n    ...baseline.dirty.keys(),\n    ...current.dirty.keys(),\n    ...committedPaths(baseline.commit, current.commit),\n  ]);\n  const all = [...keys];\n  const startTree = treeIdentities(baseline.commit, all);\n  const currentTree = treeIdentities(current.commit, all);\n  let changed = 0;\n  for (const key of all) {\n    const start = baseline.dirty.get(key) ?? startTree.get(key);\n    if (Buffer.from(key, 'base64').subarray(0, ARCHON_DIR.length).equals(ARCHON_DIR)) {\n      // Only commits count here: the committed entry must have changed since the start,\n      // and must differ from what the path held at the start -- so a new commit that\n      // leaves a pre-existing uncommitted file alone, or commits its bytes as they were,\n      // is not new work.\n      const committed = currentTree.get(key);\n      if (!same(committed, startTree.get(key)) && !same(committed, start)) changed++;\n      continue;\n    }\n    const now = current.dirty.get(key) ?? currentTree.get(key);\n    if (!same(now, start)) changed++;\n  }\n  return changed;\n}\n\ntype Decision = { readonly shown: string } | { readonly refusal: string };\n\nfunction decide(): Decision {\n  // The loop's verdict, bound by the workflow (`with:`): green as canonical boolean\n  // text (\"true\"/\"false\"), the declared cause of any red, and the summary that carries\n  // the evidence for it. `baseline` is the implement invocation's checkout start.\n  const green = trimmed(process.env.INPUTS_GREEN);\n  // Certified at the loop's own node: `red_cause` is an enum on its output_format,\n  // so the value here is a member or the empty string, never something to re-check.\n  const declaredCause = trimmed(process.env.INPUTS_RED_CAUSE);\n  const summary = trimmed(process.env.INPUTS_SUMMARY);\n  const baselineText = trimmed(process.env.INPUTS_BASELINE);\n  const executionText = trimmed(process.env.ARCHON_NODE_EXECUTION);\n  if (declaredCause === 'incomplete') {\n    return { refusal: unfinishedValidation('The implementation', summary) };\n  }\n\n  let unknownReason: string | undefined;\n  let execution: unknown;\n  try {\n    execution = JSON.parse(executionText);\n  } catch {\n    execution = undefined;\n  }\n  let baselineValue: unknown;\n  try {\n    baselineValue = JSON.parse(baselineText);\n  } catch {\n    baselineValue = undefined;\n  }\n  const runId = isRecord(execution) && typeof execution.runId === 'string' ? execution.runId : '';\n  const attempt = isRecord(execution) && isRecord(execution.attempt) ? execution.attempt : undefined;\n  const baseline = readObservation('the implement start', baselineValue, runId);\n  const current = readObservation('the current checkout', attempt?.checkoutStart, runId);\n  if ('unknown' in baseline) unknownReason = baseline.unknown;\n  else if ('unknown' in current) unknownReason = current.unknown;\n  else {\n    const changed = contentChanges(baseline.observed, current.observed);\n    if (changed > 0) {\n      return { shown: `${String(changed)} path(s) changed since this implement invocation started` };\n    }\n  }\n\n  const base = process.env.BASE_BRANCH ?? '';\n  if (green === 'true' && base !== '') {\n    const lead = commitsAheadOfBase(base);\n    if (lead !== undefined && lead.ahead > 0) {\n      return {\n        shown:\n          'no new changes this run; verified existing work -- ' +\n          `${lead.ahead} commit(s) ahead of ${lead.ref}`,\n      };\n    }\n  }\n\n  // Nothing to show, and nothing to do about it. The evidence bar is the green gates'\n  // own: emptiness is all that is checked, because whether the prose names a real\n  // failing check is the declaring agent's judgment and the reviewer's.\n  if (green !== 'true' && passesRed(declaredCause) && summary !== '') {\n    return {\n      shown: `no new changes this run; the remaining red is declared ${declaredCause}, not introduced`,\n    };\n  }\n\n  return {\n    refusal:\n      (unknownReason !== undefined\n        ? `implement's new work cannot be established: ${unknownReason}. `\n        : 'implement changed no content outside .archon/ since this invocation started ' +\n          '(pre-existing uncommitted changes are part of that start), ') +\n      'and the branch carries no verified work ahead of the base ' +\n      `(green=${green || 'unknown'}, red_cause=${declaredCause || 'unknown'}).\\n` +\n      'Nothing to show is only acceptable on red the change did not cause -- declared ' +\n      `${PASSES_RED.join(' or ')}, with the failing check named in the summary. Red the ` +\n      'change introduced, red nobody explained, and a cause with no evidence behind it ' +\n      'fail here rather than reporting success.',\n  };\n}\n\nconst decision = decide();\nif ('shown' in decision) {\n  report(decision.shown);\n} else {\n  refuse(decision.refusal);\n}\n","pr/scripts/publish-pr.ts":"/**\n * Publish the prepared pull request and record its verified identity.\n *\n * The preceding node judges: it establishes the target, writes the body, pushes\n * the branch, and names the pull request the run was launched onto when there is\n * one. This node owns the public write and proves it landed, through whichever\n * source the run selected.\n *\n * Whether this work already has a pull request is decided here, not in a prompt:\n * an open pull request for the recorded head IS the pull request, and a second\n * one is never opened for it.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_INTENT: path to the JSON intent the preparing node wrote.\n */\n\nimport { readFileSync } from 'node:fs';\nimport { createPr, findOpenPrByHead, viewPr } from '../../.shared/pr.ts';\nimport {\n  forgeSource,\n  record,\n  sameRepo,\n  type PrRecord,\n  type QualifiedPr,\n} from '../../.shared/forge.ts';\nimport { emit, note, refuse, text } from '../../.shared/io.ts';\n\nfunction repo(value: unknown, field: string): QualifiedPr['repo'] {\n  const parsed = record(value);\n  if (\n    typeof parsed?.host !== 'string' ||\n    parsed.host.trim() === '' ||\n    typeof parsed.path !== 'string' ||\n    parsed.path.trim() === ''\n  ) {\n    throw new Error(`the PR intent's ${field} must name a host and an owner/repo path`);\n  }\n  return { host: parsed.host, path: parsed.path };\n}\n\nfunction required(value: unknown, field: string): string {\n  if (typeof value !== 'string' || value.trim() === '') {\n    throw new Error(`the PR intent's ${field} must be a non-empty string`);\n  }\n  return value;\n}\n\nfunction publish(): PrRecord {\n  const source = forgeSource(process.env.ARCHON_SDLC_FORGE);\n  const intent = record(JSON.parse(readFileSync(text(process.env.INPUTS_INTENT), 'utf8')));\n  if (!intent) throw new Error('the PR intent must be a JSON object');\n  const base = repo(intent.repo, 'repo');\n  const headRepo = intent.headRepo === undefined ? base : repo(intent.headRepo, 'headRepo');\n  const head = required(intent.head, 'head');\n\n  // The run was launched onto an existing pull request: it names the number, and\n  // its draft state belongs to its author, not to this run's draft input.\n  if (intent.existing !== undefined) {\n    if (typeof intent.existing !== 'number' || !Number.isInteger(intent.existing)) {\n      throw new Error(\"the PR intent's existing must be the pull request number\");\n    }\n    const view = viewPr({ repo: base, number: intent.existing }, source);\n    const observedHead = view.pr.head_repo;\n    if (view.pr.head !== head || observedHead === null || !sameRepo(observedHead, headRepo)) {\n      throw new Error(\n        `pull request ${String(intent.existing)} has head ${String(view.pr.head_repo?.path)}:${view.pr.head}, not the recorded ${headRepo.path}:${head}`\n      );\n    }\n    return view.pr;\n  }\n\n  const existing = findOpenPrByHead(base, headRepo, head, source);\n  if (existing) {\n    note(`publish-pr: ${existing.pr.url} already has this head, so no pull request was opened.`);\n    return existing.pr;\n  }\n  if (typeof intent.draft !== 'boolean') throw new Error(\"the PR intent's draft must be a boolean\");\n  return createPr(\n    {\n      repo: base,\n      headRepo,\n      head,\n      headRevision: required(intent.headRevision, 'headRevision'),\n      base: required(intent.base, 'base'),\n      title: required(intent.title, 'title'),\n      bodyPath: required(intent.bodyPath, 'bodyPath'),\n      draft: intent.draft,\n    },\n    source\n  );\n}\n\ntry {\n  emit(publish());\n} catch (error) {\n  refuse(`publish-pr: ${error instanceof Error ? error.message : String(error)}`);\n}\n","review/scripts/publish-review.ts":"/**\n * Publish the review report as the pull request's one canonical comment.\n *\n * The reviewer judges and writes the report; this node owns the public write, so\n * every round edits the same marked comment instead of appending another. A\n * review whose scope was a working diff has no pull request and publishes\n * nothing. The verdict passes through unchanged either way: publication is not\n * what makes a review true.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_SCOPE: the review's requested scope. Delivery passes its verified\n *   pull-request record here, and that record is then the only write target.\n * - INPUTS_PR: the qualified pull request the scope agent declared it reviewed,\n *   or `{}` for a working diff. It names the target of a standalone review.\n * - INPUTS_REPORT: path to the report this node publishes.\n * - INPUTS_READY / INPUTS_ACTION / INPUTS_SUMMARY / INPUTS_REPORT_POINTER: the\n *   certified verdict fields this node forwards.\n */\n\nimport { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport { upsertComment } from '../../.shared/pr.ts';\nimport {\n  forgeSource,\n  parseQualifiedPr,\n  record,\n  sameRepo,\n  type QualifiedPr,\n} from '../../.shared/forge.ts';\nimport { emit, note, refuse, text } from '../../.shared/io.ts';\n\nconst MARKER = '<!-- archon-review-report -->';\n\n/** The pull request delivery recorded, when the scope is that JSON record. */\nfunction recordedPr(scope: string): QualifiedPr | undefined {\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(scope);\n  } catch {\n    return undefined; // a PR URL, a branch name, or empty\n  }\n  return record(parsed) ? parseQualifiedPr(scope) : undefined;\n}\n\n/** The pull request the scope agent declared, or undefined for a working diff. */\nfunction declaredPr(value: string): QualifiedPr | undefined {\n  const target = value.trim() || '{}';\n  const parsed: unknown = JSON.parse(target);\n  if (parsed === null || (typeof parsed === 'object' && Object.keys(parsed).length === 0)) {\n    return undefined;\n  }\n  return parseQualifiedPr(target);\n}\n\nfunction label(pr: QualifiedPr | undefined): string {\n  return pr ? `${pr.repo.host}/${pr.repo.path}#${String(pr.number)}` : 'no pull request';\n}\n\ntry {\n  const source = forgeSource(process.env.ARCHON_SDLC_FORGE);\n  const verdict = {\n    ready: JSON.parse(text(process.env.INPUTS_READY)) as boolean,\n    action: text(process.env.INPUTS_ACTION),\n    findings_summary: text(process.env.INPUTS_SUMMARY),\n    report: JSON.parse(text(process.env.INPUTS_REPORT_POINTER)) as unknown,\n  };\n  const recorded = recordedPr(text(process.env.INPUTS_SCOPE));\n  const declared = declaredPr(text(process.env.INPUTS_PR));\n  if (\n    recorded &&\n    (declared?.number !== recorded.number || !sameRepo(declared.repo, recorded.repo))\n  ) {\n    throw new Error(\n      `the review scope declared ${label(declared)}, but delivery recorded ${label(recorded)}`\n    );\n  }\n  const pr = recorded ?? declared;\n  if (!pr) {\n    note('publish-review: the review scope is a working diff, so no comment was published.');\n    emit(verdict);\n  } else {\n    const directory = mkdtempSync(join(tmpdir(), 'archon-review-'));\n    try {\n      const marked = join(directory, 'comment.md');\n      const report = readFileSync(text(process.env.INPUTS_REPORT), 'utf8');\n      if (report.trim() === '') throw new Error('the review report is empty');\n      writeFileSync(marked, `${MARKER}\\n${report}`);\n      const comment = upsertComment(pr, MARKER, marked, source);\n      note(`publish-review: canonical review comment at ${comment.url}`);\n    } finally {\n      rmSync(directory, { recursive: true, force: true });\n    }\n    emit(verdict);\n  }\n} catch (error) {\n  refuse(`publish-review: ${error instanceof Error ? error.message : String(error)}`);\n}\n","ship/scripts/outcome.ts":"/**\n * One return for every legitimate terminal result of the routed fix chain.\n *\n * Negative advisory verdicts complete with the report that explains them; delivery is\n * accepted when the deliver branch actually ran and handed back the pull request it\n * opened. `delivered` is this workflow's authored outcome: an honest \"no work is\n * owed\" is a successful run that shipped nothing, and the two facts are separate.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_ROUTE / INPUTS_SUMMARY: triage's verdict.\n * - INPUTS_DELIVERED: `$deliver.output.pr_url`, the flip's certified URL, or \"null\"\n *   when the deliver branch was skipped (no_action, or an advisory stop upstream of\n *   the gates). The value is validated at the producer, so nothing here re-reads it\n *   for URL shape.\n *\n * A delivery that STARTED and died no longer reaches this node at all: the failure\n * cascades an `upstream_failed` skip that blocks this join, and the run's terminal\n * record names the node that actually failed. The spend gates' outputs used to be\n * bound here purely to tell that case apart from an advisory stop.\n */\n\nimport { artifactsDir, emit, refuse, text } from '../../.shared/io.ts';\nimport { caveats } from '../../.shared/report.ts';\n\n/**\n * The advisory report a route stopped at, when stopping there is a valid result.\n *\n * Keyed by plain string on purpose. Which routes exist is triage's vocabulary,\n * declared in its own schema; re-enumerating it here would be a second owner that\n * nothing keeps in step. A route this table does not know still cannot reach a\n * delivered report — it opens no spend gate, so it always arrives with no delivered\n * value and refuses through the branch below.\n */\nconst ADVISORY_STOP: Record<string, { readonly reason: string; readonly report: string } | undefined> =\n  {\n    investigate: {\n      reason: 'the investigation did not establish a safe fix boundary',\n      report: 'investigation.md',\n    },\n    plan: { reason: 'planning left a material decision unresolved', report: 'plan.md' },\n  };\n\nconst artifacts = artifactsDir();\nconst listingFile = process.env.TYPED_ARTIFACTS_FILE;\nconst route = text(process.env.INPUTS_ROUTE);\nconst summary = text(process.env.INPUTS_SUMMARY);\nconst delivered = text(process.env.INPUTS_DELIVERED) || 'null';\n\nif (route === 'no_action') {\n  emit({\n    delivered: false,\n    summary:\n      `No delivery needed: ${summary}\\nReport: ${artifacts}/triage.md` +\n      caveats(artifacts, { failed: false, listingFile }),\n  });\n} else if (delivered === 'null') {\n  const stop = ADVISORY_STOP[route];\n  if (stop === undefined) {\n    refuse(\n      `outcome: route '${route}' skipped delivery without an advisory report ` +\n        'to point to.' +\n        caveats(artifacts, { failed: true, listingFile })\n    );\n  } else {\n    emit({\n      delivered: false,\n      summary:\n        `No delivery started: ${stop.reason}.\\nReport: ${artifacts}/${stop.report}` +\n        caveats(artifacts, { failed: false, listingFile }),\n    });\n  }\n} else {\n  // Deliver ran, so the record it returned is the report.\n  emit({ delivered: true, summary: delivered + caveats(artifacts, { failed: false, listingFile }) });\n}\n","triage/scripts/verdict.ts":"/**\n * Validate the triage verdict before it routes work, and apply its labels.\n *\n * The prompt judges; this boundary verifies what a schema cannot. Each field's type\n * and vocabulary — the contract, route, and complexity enums, the item and edit\n * shapes, the report pointer — were certified by the engine on the node that\n * produced them, so nothing here re-checks membership. What remains is the relations\n * between fields: only a READY contract carries an engineering route, design-first\n * is a READY item routed to plan, only NEEDS_CONTRACT_WORK proposes edits, only\n * BLOCKED names blockers, and blockers are qualified URLs. The pack's own labels\n * derive from the declared fields here rather than being chosen by the model, and\n * only when the run was launched with publish=true and the target is a tracker\n * issue does this verify the item's identity on the tracker, apply the labels, and\n * read them back. Area labels are never created: the prompt may only pick labels\n * the repository already has. gh is the interim transport; the forge contract's\n * work-item operation is the intended owner.\n */\n\nimport { emit, refuse, text, trimmed } from '../../.shared/io.ts';\n\ntype Contract = 'READY' | 'NEEDS_CONTRACT_WORK' | 'BLOCKED' | 'NO_ACTION';\ntype Complexity = 'small' | 'risky' | 'large';\n\n// Exactly one state label per item. Design-first is READY whose next step is\n// design, so it replaces the ready label rather than sitting beside it.\nconst STATE_LABEL: Record<Contract, string> = {\n  READY: 'archon-ready',\n  NEEDS_CONTRACT_WORK: 'archon-needs-contract',\n  BLOCKED: 'archon-blocked',\n  NO_ACTION: 'archon-close',\n};\nconst DESIGN_FIRST_LABEL = 'archon-design-first';\nconst COMPLEXITY_LABEL: Record<Complexity, string> = {\n  small: 'archon-small',\n  risky: 'archon-risky',\n  large: 'archon-large',\n};\nconst PACK_LABELS: Record<string, { color: string; description: string }> = {\n  'archon-ready': { color: '0E8A16', description: 'Triage: the contract is ready for a run' },\n  'archon-needs-contract': {\n    color: 'D93F0B',\n    description: \"Triage: one of the contract's six elements is missing\",\n  },\n  'archon-blocked': {\n    color: 'B60205',\n    description: 'Triage: a prerequisite or human decision must land first',\n  },\n  'archon-close': {\n    color: '6A737D',\n    description: 'Triage: already delivered, duplicate, obsolete, or out of direction',\n  },\n  'archon-design-first': {\n    color: '5319E7',\n    description: 'Triage: ready, but settle the engineering shape before implementing',\n  },\n  'archon-small': { color: 'C2E0C6', description: 'Triage: bounded change' },\n  'archon-risky': {\n    color: 'FBCA04',\n    description: 'Triage: touches auth, data, a destructive path, or a compatibility boundary',\n  },\n  'archon-large': {\n    color: 'F9D0C4',\n    description: 'Triage: several packages or schemas, or an unsettled shape',\n  },\n};\n\ninterface Item {\n  readonly repository: string;\n  readonly number: number;\n}\ninterface Edits {\n  readonly title: string;\n  readonly body: string;\n}\n\n/** A `from:` binding arrives as the producer's JSON, already certified against its schema. */\nfunction bound(value: string | undefined): unknown {\n  return JSON.parse(text(value));\n}\n\nfunction isQualifiedUrl(value: string): boolean {\n  if (value === '' || /\\s/.test(value)) return false;\n  try {\n    const url = new URL(value);\n    return (url.protocol === 'http:' || url.protocol === 'https:') && url.hostname !== '';\n  } catch {\n    return false;\n  }\n}\n\nfunction gh(...args: string[]): string {\n  const result = Bun.spawnSync(['gh', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  if (result.exitCode !== 0) {\n    throw new Error(`gh ${args.slice(0, 3).join(' ')} failed: ${result.stderr.toString().trim()}`);\n  }\n  return result.stdout.toString();\n}\n\nfunction existingLabels(repository: string): Set<string> {\n  const rows = JSON.parse(\n    gh('label', 'list', '--repo', repository, '--limit', '500', '--json', 'name')\n  ) as { name: string }[];\n  return new Set(rows.map(row => row.name));\n}\n\n/** The item's current labels, after proving the number names the issue the prompt declared. */\nfunction readIssue(item: Item): Set<string> {\n  const issue = JSON.parse(gh('api', `repos/${item.repository}/issues/${String(item.number)}`)) as {\n    number?: unknown;\n    html_url?: unknown;\n    pull_request?: unknown;\n    labels?: { name: string }[];\n  };\n  const url = `https://github.com/${item.repository}/issues/${String(item.number)}`;\n  if (\n    issue.number !== item.number ||\n    (typeof issue.html_url === 'string' ? issue.html_url : '').toLowerCase() !== url.toLowerCase() ||\n    'pull_request' in issue\n  ) {\n    throw new Error(`tracker identity mismatch: ${url} is not the issue the verdict names`);\n  }\n  return new Set((issue.labels ?? []).map(row => row.name));\n}\n\nfunction apply(item: Item, wanted: string[], area: string[]): string[] {\n  const current = readIssue(item);\n  const present = existingLabels(item.repository);\n  for (const name of wanted) {\n    if (!present.has(name)) {\n      const { color, description } = PACK_LABELS[name];\n      gh('label', 'create', name, '--repo', item.repository, '--color', color, '--description', description);\n    }\n  }\n  const areaPresent = area.filter(name => present.has(name));\n  const stale = [...current].filter(name => name in PACK_LABELS && !wanted.includes(name)).sort();\n  const toAdd = [...new Set([...wanted, ...areaPresent])].filter(name => !current.has(name)).sort();\n  // Narrow add and remove operations, never a whole-set write, so labels an\n  // operator adds concurrently survive.\n  if (toAdd.length > 0 || stale.length > 0) {\n    const args = ['issue', 'edit', String(item.number), '--repo', item.repository];\n    for (const name of toAdd) args.push('--add-label', name);\n    for (const name of stale) args.push('--remove-label', name);\n    gh(...args);\n  }\n  const after = readIssue(item);\n  const missing = [...wanted, ...areaPresent].filter(name => !after.has(name));\n  const lingering = stale.filter(name => after.has(name));\n  if (missing.length > 0 || lingering.length > 0) {\n    throw new Error(\n      `label read-back disagrees: missing=${JSON.stringify(missing)} lingering=${JSON.stringify(lingering)}`\n    );\n  }\n  return [...new Set([...wanted, ...areaPresent])].sort();\n}\n\nfunction main(): void {\n  const contract = text(process.env.INPUTS_CONTRACT) as Contract;\n  const route = text(process.env.INPUTS_ROUTE);\n  const complexity = text(process.env.INPUTS_COMPLEXITY) as Complexity;\n  const designFirst = text(process.env.INPUTS_DESIGN_FIRST) === 'true';\n  const publish = text(process.env.INPUTS_PUBLISH) === 'true';\n  const summary = text(process.env.INPUTS_SUMMARY);\n  const blockedReason = text(process.env.INPUTS_BLOCKED_REASON);\n  const area = bound(process.env.INPUTS_AREA_LABELS) as string[];\n  const boundItem = bound(process.env.INPUTS_ITEM) as Item;\n  const edits = bound(process.env.INPUTS_PROPOSED_EDITS) as Edits;\n  const blockedBy = bound(process.env.INPUTS_BLOCKED_BY) as string[];\n  const report = bound(process.env.INPUTS_REPORT);\n  // An empty repository is the prompt's spelling for \"not a tracker issue\".\n  const item = boundItem.repository === '' ? undefined : boundItem;\n\n  const invalid = (message: string): void => {\n    refuse(`invalid triage verdict: ${message}`);\n  };\n\n  if ((contract === 'READY') !== (route !== 'no_action')) {\n    invalid(\n      `only a READY contract carries an engineering route: got contract=${contract} route=${route}`\n    );\n    return;\n  }\n  if (designFirst && route !== 'plan') {\n    invalid(`design_first requires route=plan, got route=${route}`);\n    return;\n  }\n  const proposes = edits.title.trim() !== '' && edits.body.trim() !== '';\n  if (contract === 'NEEDS_CONTRACT_WORK' && !proposes) {\n    invalid('NEEDS_CONTRACT_WORK requires a proposed title and body');\n    return;\n  }\n  if (contract !== 'NEEDS_CONTRACT_WORK' && (edits.title !== '' || edits.body !== '')) {\n    invalid('only NEEDS_CONTRACT_WORK proposes edits');\n    return;\n  }\n  if (!blockedBy.every(isQualifiedUrl)) {\n    invalid('blocked_by must be a list of fully qualified http(s) URLs');\n    return;\n  }\n  if (contract === 'BLOCKED' && trimmed(blockedReason) === '') {\n    invalid('BLOCKED requires a blocked_reason');\n    return;\n  }\n  if (contract !== 'BLOCKED' && (blockedReason !== '' || blockedBy.length > 0)) {\n    invalid('only BLOCKED names a blocker');\n    return;\n  }\n  if (trimmed(summary) === '') {\n    invalid('summary is empty');\n    return;\n  }\n  if (area.some(name => name === '')) {\n    invalid('area_labels must be label names');\n    return;\n  }\n  if (area.some(name => name in PACK_LABELS)) {\n    // The state and size labels are derived below; a pack label smuggled in as an\n    // area label would be added beside the derived state or removed as stale.\n    invalid('area_labels may not name a pack label; those derive from the verdict');\n    return;\n  }\n  if (item !== undefined && (!item.repository.includes('/') || item.number <= 0)) {\n    invalid('item must be {repository: owner/repo, number: N} or carry an empty repository');\n    return;\n  }\n\n  let labels = [designFirst ? DESIGN_FIRST_LABEL : STATE_LABEL[contract]];\n  // Size only matters on an item that can still be worked; a close verdict carries none.\n  if (contract !== 'NO_ACTION') labels.push(COMPLEXITY_LABEL[complexity]);\n\n  let published = false;\n  if (publish && item !== undefined) {\n    labels = apply(item, labels, area);\n    published = true;\n  } else {\n    labels = [...new Set([...labels, ...area])].sort();\n  }\n\n  emit({\n    contract,\n    route,\n    ready: contract === 'READY',\n    design_first: designFirst,\n    complexity,\n    labels,\n    published,\n    proposed_edits: { title: edits.title, body: edits.body },\n    blocked_reason: blockedReason,\n    blocked_by: blockedBy,\n    summary,\n    report,\n  });\n}\n\nmain();\n","upkeep/scripts/outcome.ts":"/**\n * One return for every legitimate terminal result of the upkeep chain.\n *\n * A no_action assessment completes with the report that explains it; a delivered\n * update is accepted when the deliver branch actually ran and handed back the pull\n * request it opened. `delivered` is this workflow's authored outcome: the run\n * succeeded either way, and whether an update shipped is a separate fact.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_ACTION / INPUTS_SUMMARY: the assessment's verdict.\n * - INPUTS_DELIVERED: `$deliver.output.pr_url`, the flip's certified URL, or \"null\"\n *   when the deliver branch was skipped (no_action). The value is validated at the\n *   producer, so nothing here re-reads it for URL shape.\n *\n * A delivery that STARTED and died no longer reaches this node at all: the failure\n * cascades an `upstream_failed` skip that blocks this join, and the run's terminal\n * record names the node that actually failed.\n */\n\nimport { artifactsDir, emit, refuse, text } from '../../.shared/io.ts';\nimport { caveats } from '../../.shared/report.ts';\n\n// Which actions exist is the assessment's vocabulary, declared in its own schema.\n// Re-enumerating it here would be a second owner that nothing keeps in step, and an\n// action this script does not recognise cannot open the spend gate, so it always\n// arrives with no delivered value and refuses through the branch below.\nconst artifacts = artifactsDir();\nconst listingFile = process.env.TYPED_ARTIFACTS_FILE;\nconst action = text(process.env.INPUTS_ACTION);\nconst summary = text(process.env.INPUTS_SUMMARY);\nconst delivered = text(process.env.INPUTS_DELIVERED) || 'null';\n\nif (action === 'no_action') {\n  emit({\n    delivered: false,\n    summary:\n      `No update needed: ${summary}\\nReport: ${artifacts}/upkeep-assessment.md` +\n      caveats(artifacts, { failed: false, listingFile }),\n  });\n} else if (delivered === 'null') {\n  refuse(\n    \"outcome: the assessment chose 'update' but delivery never ran — \" +\n      \"see the run's terminal record for the node it stopped at.\" +\n      caveats(artifacts, { failed: true, listingFile })\n  );\n} else {\n  // Deliver ran, so the record it returned is the report.\n  emit({ delivered: true, summary: delivered + caveats(artifacts, { failed: false, listingFile }) });\n}\n","validate/scripts/compare.ts":"import { relative } from 'node:path';\nimport { compareComposition, readComparisonRequest } from '../../.shared/composition.ts';\nimport { artifactsDir, emit, trimmed } from '../../.shared/io.ts';\n\nconst request = readComparisonRequest(trimmed(process.env.INPUTS_COMPARISON));\nconst runId = process.env.WORKFLOW_ID;\nif (!runId) throw new Error('WORKFLOW_ID is required for composition artifact attribution.');\nconst artifacts = artifactsDir();\nconst result = await compareComposition(process.cwd(), artifacts, request);\nemit({\n  ...result.verdict,\n  evidence: {\n    type: 'archon_artifact',\n    run_id: runId,\n    path: relative(artifacts, result.path).split('\\\\').join('/'),\n  },\n});\n","validate/scripts/mode.ts":"import { emit } from '../../.shared/io.ts';\n\nconst comparison = process.env.INPUTS_COMPARISON ?? '';\nif (comparison !== '' && comparison.trim() === '') {\n  throw new Error('Comparison path must not contain only whitespace.');\n}\nemit({ comparison: comparison !== '' });\n","validate/scripts/result.ts":"import { emit, text } from '../../.shared/io.ts';\n\n// Each producer is certified by its node's schema. The comparison path and the\n// ordinary path are exclusive; on the ordinary path, `run` is null only when its\n// timeout stopped the gate, and `classify` ran exactly when `run` reported red.\nconst comparison: unknown = JSON.parse(text(process.env.INPUTS_COMPARISON));\nconst run = JSON.parse(text(process.env.INPUTS_RUN)) as {\n  status: 'green' | 'red' | 'incomplete';\n  summary: string;\n} | null;\nconst classification = JSON.parse(text(process.env.INPUTS_CLASSIFICATION)) as {\n  red_cause: 'introduced' | 'inherited' | 'environment';\n  summary: string;\n} | null;\n\nif (comparison !== null) {\n  if (run !== null || classification !== null) {\n    throw new Error('Validation requires exactly one executed path.');\n  }\n  emit(comparison);\n} else if (run === null) {\n  emit({\n    green: false,\n    red_cause: 'incomplete',\n    summary:\n      \"The project gate didn't finish: the check runner's time limit stopped it. \" +\n      'validation.md records which checks ran and which never did.',\n    evidence: null,\n  });\n} else if (run.status === 'red') {\n  if (classification === null) throw new Error('A red gate reached the result unclassified.');\n  emit({\n    green: false,\n    red_cause: classification.red_cause,\n    summary: classification.summary,\n    evidence: null,\n  });\n} else {\n  emit({\n    green: run.status === 'green',\n    red_cause: run.status === 'green' ? '' : 'incomplete',\n    summary: run.summary,\n    evidence: null,\n  });\n}\n","validate/scripts/run-checks.ts":"/**\n * Runs the checks `discover` declared, in order, and records what happened.\n *\n * Every exit status lands in `$ARTIFACTS_DIR/validation.md`, rewritten after each\n * check so the record is current if the node is stopped. Each check's full output\n * goes to its own log under `$ARTIFACTS_DIR/validation/`. The first failing check\n * ends the run: later checks are recorded as never run, which is how the project's\n * own aggregate gates behave.\n *\n * The status is read from exit statuses alone:\n * - `red`: a check ran and exited non-zero, or was killed by a signal it did not\n *   get from this script. `classify` judges why.\n * - `incomplete`: no check failed, but one could not be started.\n * - `green`: every declared check ran and exited 0. No declared checks is green only\n *   because `discover` judged that the project defines none; its notes say so.\n *\n * No timer lives here. The node's `timeout:` is the only one, and the engine stops\n * this script with SIGTERM when it expires. The handler below then stops the\n * running check's whole process tree, restores anything quarantined, records the\n * stop, and re-raises the signal so the engine sees a timeout rather than a result.\n */\n\nimport { spawn, spawnSync, type ChildProcess } from 'node:child_process';\nimport { closeSync, cpSync, existsSync, mkdirSync, openSync, readFileSync, rmSync, writeFileSync } from 'node:fs';\nimport { isAbsolute, join, normalize } from 'node:path';\nimport { artifactsDir, emit, text } from '../../.shared/io.ts';\nimport { projectEnvironment } from '../../.shared/node-env.ts';\n\ninterface Check {\n  name: string;\n  argv: string[];\n}\n\ninterface Discovery {\n  checks: Check[];\n  quarantine: string[];\n  notes: string;\n}\n\ntype Outcome =\n  | { kind: 'passed' }\n  | { kind: 'failed'; exitCode: number | null; signal: string | null }\n  | { kind: 'not-started'; error: string }\n  | { kind: 'stopped'; signal: string }\n  | { kind: 'running' }\n  | { kind: 'never-ran' };\n\ninterface Entry {\n  check: Check;\n  log: string;\n  outcome: Outcome;\n  seconds: number | null;\n}\n\n// `discover`'s output is certified against its node's schema before it is bound here.\nconst discovery = JSON.parse(text(process.env.INPUTS_DISCOVERY)) as Discovery;\nconst cwd = process.cwd();\nconst artifacts = artifactsDir();\nconst logDir = join(artifacts, 'validation');\nconst quarantineDir = join(logDir, 'quarantine');\nconst report = join(artifacts, 'validation.md');\n// The checks run as the project's own gate, not as part of this run.\nconst gateEnv = projectEnvironment(process.env);\n\nconst TAIL_LINES = 60;\n\nfunction describe(outcome: Outcome): string {\n  switch (outcome.kind) {\n    case 'passed':\n      return 'passed (exit 0)';\n    case 'failed':\n      return outcome.signal === null\n        ? `failed (exit ${String(outcome.exitCode)})`\n        : `failed (killed by ${outcome.signal})`;\n    case 'not-started':\n      return `could not start: ${outcome.error}`;\n    case 'stopped':\n      return `did not finish: the node's time limit stopped it (${outcome.signal})`;\n    case 'running':\n      return 'running';\n    case 'never-ran':\n      return 'never ran';\n  }\n}\n\nfunction tail(path: string): string {\n  if (!existsSync(path)) return '';\n  const lines = readFileSync(path, 'utf8').trimEnd().split('\\n');\n  return lines.slice(-TAIL_LINES).join('\\n');\n}\n\nfunction render(entries: readonly Entry[], quarantined: readonly string[]): void {\n  const lines = ['# Validation', ''];\n  if (discovery.notes.trim() !== '') lines.push(discovery.notes.trim(), '');\n  if (entries.length === 0) lines.push('The project defines no checks, so none ran.', '');\n  if (quarantined.length > 0) {\n    lines.push(\n      'Moved aside while the checks ran (untracked run scaffolding):',\n      ...quarantined.map(path => `- \\`${path}\\``),\n      ''\n    );\n  }\n  if (kept.length > 0) {\n    lines.push(\n      'Not restored, because the checkout already had the path again. The moved copy is kept at:',\n      ...kept.map(path => `- \\`${path}\\``),\n      ''\n    );\n  }\n  for (const [index, entry] of entries.entries()) {\n    const seconds = entry.seconds === null ? '' : ` after ${entry.seconds.toFixed(0)}s`;\n    lines.push(`## ${String(index + 1)}. ${entry.check.name}`, '');\n    lines.push(`\\`${entry.check.argv.join(' ')}\\` ${describe(entry.outcome)}${seconds}.`);\n    const kind = entry.outcome.kind;\n    if (kind === 'failed' || kind === 'stopped' || kind === 'not-started') {\n      const output = tail(entry.log);\n      if (output !== '') {\n        lines.push('', `Last ${String(TAIL_LINES)} lines of output:`, '', '```', output, '```');\n      }\n    }\n    if (kind !== 'never-ran' && kind !== 'not-started') lines.push('', `Full output: \\`${entry.log}\\``);\n    lines.push('');\n  }\n  writeFileSync(report, `${lines.join('\\n').trimEnd()}\\n`);\n}\n\n/** Git's view of a path: whether anything at or under it is tracked. */\nfunction tracked(path: string): boolean {\n  const result = spawnSync('git', ['ls-files', '--', path], { cwd, encoding: 'utf8' });\n  if (result.status !== 0) {\n    throw new Error(`git ls-files failed for quarantine path '${path}': ${result.stderr}`);\n  }\n  return result.stdout.trim() !== '';\n}\n\n/**\n * The quarantine boundary. Only untracked run scaffolding under `.archon/` may move:\n * never a tracked file, and never anything outside that directory.\n */\nfunction quarantinable(path: string): string {\n  const normal = normalize(path).split('\\\\').join('/');\n  if (isAbsolute(path) || normal.split('/').includes('..') || !normal.startsWith('.archon/')) {\n    throw new Error(`Refusing to quarantine '${path}': only paths under .archon/ may move.`);\n  }\n  if (!existsSync(join(cwd, normal))) {\n    throw new Error(`Refusing to quarantine '${path}': it does not exist.`);\n  }\n  if (tracked(normal)) {\n    throw new Error(`Refusing to quarantine '${path}': git tracks files there.`);\n  }\n  return normal;\n}\n\n/** A path moved out of the checkout, and where its copy lives until it goes back. */\ninterface Moved {\n  path: string;\n  copy: string;\n}\n\n// Every attempt moves into its own directory, so a copy an earlier attempt kept is\n// never merged into or overwritten by a later one.\nconst attemptDir = join(quarantineDir, `${String(Date.now())}-${String(process.pid)}`);\n\n// The moves not yet undone, mirrored to disk before each original is removed. An\n// attempt that dies without restoring (on Windows, or after SIGKILL, the engine stops\n// this script with no signal to catch) leaves the list for the next attempt.\nconst manifest = join(logDir, 'quarantine.json');\nconst pending: Moved[] = existsSync(manifest)\n  ? (JSON.parse(readFileSync(manifest, 'utf8')) as Moved[])\n  : [];\n\n/** Moved copies left in place because the checkout already had the path again. */\nconst kept: string[] = [];\n\n/**\n * Put every pending path back. A path the checkout has again is never overwritten:\n * its moved copy stays where it is and the record names it, since a stop here would\n * block every later attempt until someone intervened by hand. A copy that is already\n * gone was put back by an attempt that died before it could record that.\n */\nfunction restorePending(): void {\n  for (const { path, copy } of pending) {\n    if (!existsSync(copy)) continue;\n    if (existsSync(join(cwd, path))) {\n      kept.push(copy);\n      continue;\n    }\n    cpSync(copy, join(cwd, path), { recursive: true });\n    rmSync(copy, { recursive: true, force: true });\n  }\n  pending.length = 0;\n  rmSync(manifest, { force: true });\n}\n\n// An earlier attempt left paths moved aside. Put them back before anything is\n// validated or moved again.\nrestorePending();\n\n// Validate every path before moving any, so a refusal leaves the checkout untouched.\nconst toQuarantine = discovery.quarantine.map(quarantinable);\nconst quarantined: string[] = [];\n\nconst entries: Entry[] = discovery.checks.map((check, index) => ({\n  check,\n  log: join(logDir, `${String(index + 1)}.log`),\n  outcome: { kind: 'never-ran' },\n  seconds: null,\n}));\nlet current: { entry: Entry; child: ChildProcess; started: number } | null = null;\n\n// POSIX only: a detached child leads its own process group, so one signal reaches\n// every process the check started. Windows has no process groups, and the engine\n// ends a timed-out script there without a signal this handler could catch.\nconst ownGroup = process.platform !== 'win32';\n\nfunction stopCurrent(signal: NodeJS.Signals): void {\n  if (current === null) return;\n  const { entry, child, started } = current;\n  entry.outcome = { kind: 'stopped', signal };\n  entry.seconds = (Date.now() - started) / 1000;\n  if (child.pid === undefined) return;\n  try {\n    if (ownGroup) process.kill(-child.pid, 'SIGKILL');\n    else child.kill('SIGKILL');\n  } catch {\n    // The group already exited between its last output and this signal.\n  }\n}\n\nfunction onSignal(signal: NodeJS.Signals): void {\n  stopCurrent(signal);\n  try {\n    restorePending();\n  } finally {\n    render(entries, quarantined);\n    // Re-raise with default handling, so the engine sees the node stopped by its\n    // signal. Exiting normally here would read to the engine as a finished run.\n    process.removeAllListeners(signal);\n    process.kill(process.pid, signal);\n  }\n}\nprocess.on('SIGTERM', onSignal);\nprocess.on('SIGINT', onSignal);\n\nfunction runOne(entry: Entry): Promise<void> {\n  const fd = openSync(entry.log, 'w');\n  const started = Date.now();\n  return new Promise<void>(resolve => {\n    const [command, ...args] = entry.check.argv;\n    const child = spawn(command, args, {\n      cwd,\n      env: gateEnv,\n      stdio: ['ignore', fd, fd],\n      detached: ownGroup,\n    });\n    current = { entry, child, started };\n    entry.outcome = { kind: 'running' };\n    render(entries, quarantined);\n    // A command that cannot be spawned reports `error` and may or may not also\n    // report `close`; whichever settles the check first wins.\n    let settled = false;\n    const settle = (outcome: Outcome): void => {\n      if (settled) return;\n      settled = true;\n      current = null;\n      closeSync(fd);\n      entry.seconds = (Date.now() - started) / 1000;\n      if (entry.outcome.kind === 'running') entry.outcome = outcome;\n      resolve();\n    };\n    child.once('error', error => {\n      settle({ kind: 'not-started', error: error.message });\n    });\n    child.once('close', (exitCode, signal) => {\n      settle(exitCode === 0 ? { kind: 'passed' } : { kind: 'failed', exitCode, signal });\n    });\n  });\n}\n\nmkdirSync(logDir, { recursive: true });\ntry {\n  for (const path of toQuarantine) {\n    const copy = join(attemptDir, path);\n    cpSync(join(cwd, path), copy, { recursive: true });\n    quarantined.push(path);\n    pending.push({ path, copy });\n    writeFileSync(manifest, JSON.stringify(pending));\n    rmSync(join(cwd, path), { recursive: true, force: true });\n  }\n  for (const entry of entries) {\n    await runOne(entry);\n    if (entry.outcome.kind !== 'passed') break;\n  }\n} finally {\n  restorePending();\n  render(entries, quarantined);\n}\n\nconst failed = entries.find(entry => entry.outcome.kind === 'failed');\nconst unstarted = entries.find(entry => entry.outcome.kind === 'not-started');\nconst passed = entries.filter(entry => entry.outcome.kind === 'passed').map(entry => entry.check.name);\nconst ranPassed = passed.length === 0 ? 'No check passed before it.' : `Passed first: ${passed.join(', ')}.`;\n\nif (failed !== undefined) {\n  emit({\n    status: 'red',\n    summary: `${failed.check.name} ${describe(failed.outcome)}. ${ranPassed} See validation.md.`,\n  });\n} else if (unstarted !== undefined) {\n  emit({\n    status: 'incomplete',\n    summary: `${unstarted.check.name} ${describe(unstarted.outcome)}. ${ranPassed} Later checks never ran.`,\n  });\n} else if (entries.length === 0) {\n  emit({ status: 'green', summary: `No checks defined by this project. ${discovery.notes}`.trim() });\n} else {\n  emit({ status: 'green', summary: `Every check passed: ${passed.join(', ')}.` });\n}\n"},"scripts":{"__archon_pack__bundled:sdlc:deliver::check-ci":{"path":"deliver/scripts/check-ci.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::ci-attention-route":{"path":"deliver/scripts/ci-attention-route.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::ci-note":{"path":"deliver/scripts/ci-note.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::ci-round-result":{"path":"deliver/scripts/ci-round-result.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::flip-ready":{"path":"deliver/scripts/flip-ready.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::gate-green":{"path":"deliver/scripts/gate-green.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::gate-ready":{"path":"deliver/scripts/gate-ready.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::outcome":{"path":"deliver/scripts/outcome.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::publish-pr-body":{"path":"deliver/scripts/publish-pr-body.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::read-pr-body":{"path":"deliver/scripts/read-pr-body.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::resolve-review-scope":{"path":"deliver/scripts/resolve-review-scope.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:implement::assert-changed":{"path":"implement/scripts/assert-changed.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:pr::publish-pr":{"path":"pr/scripts/publish-pr.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:review::publish-review":{"path":"review/scripts/publish-review.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:ship::outcome":{"path":"ship/scripts/outcome.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:triage::verdict":{"path":"triage/scripts/verdict.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:upkeep::outcome":{"path":"upkeep/scripts/outcome.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::compare":{"path":"validate/scripts/compare.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::mode":{"path":"validate/scripts/mode.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::result":{"path":"validate/scripts/result.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::run-checks":{"path":"validate/scripts/run-checks.ts","runtime":"bun"}}},
};
